mod test_french_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::fr::french_analyzer::FrenchAnalyzer;

    fn test_analyzer() -> Result<()> {
        let fa: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::new());
        B::assert_analyzes_to(&*fa, "", &[])?;
        B::assert_analyzes_to(&*fa, "chien chat cheval", &["chien", "chat", "cheval"])?;
        B::assert_analyzes_to(&*fa, "chien CHAT CHEVAL", &["chien", "chat", "cheval"])?;
        B::assert_analyzes_to(
            &*fa,
            "  chien  ,? + = -  CHAT /: > CHEVAL",
            &["chien", "chat", "cheval"],
        )?;
        B::assert_analyzes_to(&*fa, "chien++", &["chien"])?;
        B::assert_analyzes_to(&*fa, "mot \"entreguillemet\"", &["mot", "entreguilemet"])?;
        // let's do some french specific tests now
        B::assert_analyzes_to(&*fa, "Jean-Fran\u{E7}ois", &["jean", "francoi"])?;
        // 2. stopwords
        B::assert_analyzes_to(
            &*fa,
            "le la chien les aux chat du des \u{E0} cheval",
            &["chien", "chat", "cheval"],
        )?;
        // some nouns and adjectives
        B::assert_analyzes_to(
            &*fa,
            "lances chismes habitable chiste \u{E9}l\u{E9}ments captifs",
            &["lanc", "chism", "habitabl", "chist", "element", "captif"],
        )?;
        // some verbs
        B::assert_analyzes_to(
            &*fa,
            "finissions souffrirent rugissante",
            &["finision", "soufrirent", "rugisant"],
        )?;
        // some everything else
        // aujourd'hui stays one term which is OK
        B::assert_analyzes_to(&*fa, "C3PO aujourd'hui oeuf \u{EF}\u{E2}\u{F6}\u{FB}\u{E0}\u{E4} anticonstitutionnellement Java++ ", &["c3po", "aujourd'hui", "oeuf", "\u{EF}a\u{F6}ua\u{E4}", "anticonstitutionel", "java"])?;
        // some more everything else
        // here 1940-1945 stays as one term, 1940:1945 not ?
        B::assert_analyzes_to(
            &*fa,
            "33Bis 1940-1945 1940:1945 (---i+++)*",
            &["33bi", "1940", "1945", "1940", "1945", "i"],
        )?;
        fa.close();
        Ok(())
    }

    fn test_reusable_token_stream() -> Result<()> {
        let fa: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::new());
        // stopwords
        B::assert_analyzes_to(
            &*fa,
            "le la chien les aux chat du des \u{E0} cheval",
            &["chien", "chat", "cheval"],
        )?;
        // some nouns and adjectives
        B::assert_analyzes_to(
            &*fa,
            "lances chismes habitable chiste \u{E9}l\u{E9}ments captifs",
            &["lanc", "chism", "habitabl", "chist", "element", "captif"],
        )?;
        fa.close();
        Ok(())
    }

    fn test_exclusion_table_via_ctor() -> Result<()> {
        let mut set = CharArraySet::new(1, true);
        set.add("habitable");
        let fa: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::with_stem_exclusion_set(
            CharArraySet::empty_set(),
            &set,
        ));
        B::assert_analyzes_to(&*fa, "habitable chiste", &["habitable", "chist"])?;
        fa.close();
        let fa: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::with_stem_exclusion_set(
            CharArraySet::empty_set(),
            &set,
        ));
        B::assert_analyzes_to(&*fa, "habitable chiste", &["habitable", "chist"])?;
        fa.close();
        Ok(())
    }

    fn test_elision() -> Result<()> {
        let fa: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::new());
        B::assert_analyzes_to(&*fa, "voir l'embrouille", &["voir", "embrouil"])?;
        fa.close();
        Ok(())
    }

    /// Test that stopwords are not case sensitive
    fn test_stopwords_casing() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::new());
        B::assert_analyzes_to(&*a, "Votre", &[])?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::new());
        B::check_random_data(&*random(), &a, 200 * mult())?;
        a.close();
        Ok(())
    }

    /// test accent-insensitive
    fn test_accent_insensitive() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(FrenchAnalyzer::new());
        B::check_one_term(&*a, "s\u{E9}curitaires", "securitair")?;
        B::check_one_term(&*a, "securitaires", "securitair")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.fr.TestFrenchAnalyzer")
            .method(t("testAnalyzer", test_analyzer))
            .method(t("testReusableTokenStream", test_reusable_token_stream))
            .method(t(
                "testExclusionTableViaCtor",
                test_exclusion_table_via_ctor,
            ))
            .method(t("testElision", test_elision))
            .method(t("testStopwordsCasing", test_stopwords_casing))
            .method(t("testRandomStrings", test_random_strings))
            .method(t("testAccentInsensitive", test_accent_insensitive))
            .build()
    }
}

