mod test_galician_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::gl::galician_analyzer::GalicianAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        GalicianAnalyzer::new().close();
        Ok(())
    }

    /// test stopwords and stemming
    fn test_basics() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(GalicianAnalyzer::new());
        // stemming
        B::check_one_term(&*a, "correspondente", "correspond")?;
        B::check_one_term(&*a, "corresponder\u{E1}", "correspond")?;
        // stopword
        B::assert_analyzes_to(&*a, "e", &[])?;
        a.close();
        Ok(())
    }

    /// test use of exclusion set
    fn test_exclude() -> Result<()> {
        let exclusion_set = char_set(&["correspondente"], false);
        let a: Arc<dyn Analyzer> = Arc::new(GalicianAnalyzer::with_stem_exclusion_set(
            GalicianAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(&*a, "correspondente", "correspondente")?;
        B::check_one_term(&*a, "corresponder\u{E1}", "correspond")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(GalicianAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.gl.TestGalicianAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasics", test_basics))
            .method(t("testExclude", test_exclude))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

