// TestGermanAnalyzer
// -----------------------------------------------------------------------------

mod test_german_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene::analysis::new_lower_case_filter;
    use rucene_analysis_common::analysis::core::letter_tokenizer::new_letter_tokenizer;
    use rucene_analysis_common::analysis::de::german_analyzer::GermanAnalyzer;
    use rucene_analysis_common::analysis::de::german_stem_filter::new_german_stem_filter;
    use rucene_analysis_common::analysis::miscellaneous::set_keyword_marker_filter::new_set_keyword_marker_filter;

    fn test_reusable_token_stream() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(GermanAnalyzer::new());
        B::check_one_term(&*a, "Tisch", "tisch")?;
        B::check_one_term(&*a, "Tische", "tisch")?;
        B::check_one_term(&*a, "Tischen", "tisch")?;
        a.close();
        Ok(())
    }

    fn test_with_keyword_attribute() -> Result<()> {
        let mut set = CharArraySet::new(1, true);
        set.add("fischen");
        let mut in_ = new_letter_tokenizer();
        in_.set_reader(Box::new(StringCharReader::new("Fischen Trinken")))?;
        let mut filter: Box<dyn TokenStream> = boxed(new_german_stem_filter(boxed(
            new_set_keyword_marker_filter(boxed(new_lower_case_filter(boxed(in_))?), set.clone())?,
        ))?);
        B::assert_token_stream_contents(&mut *filter, &["fischen", "trink"])?;
        Ok(())
    }

    fn test_stem_exclusion_table() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(GermanAnalyzer::with_stem_exclusion_set(
            CharArraySet::empty_set(),
            &char_set(&["tischen"], false),
        ));
        B::check_one_term(&*a, "tischen", "tischen")?;
        a.close();
        Ok(())
    }

    /// test some features of the new snowball filter these only pass with LATEST, not if you use
    /// o.a.l.a.de.GermanStemmer
    fn test_german_specials() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(GermanAnalyzer::new());
        // a/o/u + e is equivalent to the umlaut form
        B::check_one_term(&*a, "Schaltfl\u{E4}chen", "schaltflach")?;
        B::check_one_term(&*a, "Schaltflaechen", "schaltflach")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(GermanAnalyzer::new());
        B::check_random_data(&*random(), &a, 200 * mult())?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.de.TestGermanAnalyzer")
            .method(t("testReusableTokenStream", test_reusable_token_stream))
            .method(t("testWithKeywordAttribute", test_with_keyword_attribute))
            .method(t("testStemExclusionTable", test_stem_exclusion_table))
            .method(t("testGermanSpecials", test_german_specials))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

#[test]
fn test_german_analyzer() {
    run(test_german_analyzer::class);
}

