// -----------------------------------------------------------------------------
// TestNorwegianMinimalStemFilterFactory
// -----------------------------------------------------------------------------

mod test_norwegian_minimal_stem_filter_factory {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.no";

    fn test_stemming() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new(
            "eple eplet epler eplene eplets eplenes",
        ));
        let mut stream = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        stream.set_reader(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "NorwegianMinimalStem", &[])?.create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["epl", "epl", "epl", "epl", "epl", "epl"])?;
        Ok(())
    }

    /// Test stemming with variant set explicitly to Bokmål
    fn test_bokmaal_stemming() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new(
            "eple eplet epler eplene eplets eplenes",
        ));
        let mut stream = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        stream.set_reader(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "NorwegianMinimalStem", &["variant", "nb"])?
                .create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["epl", "epl", "epl", "epl", "epl", "epl"])?;
        Ok(())
    }

    /// Test stemming with variant set explicitly to Nynorsk
    fn test_nynorsk_stemming() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new(
            "gut guten gutar gutane gutens gutanes",
        ));
        let mut stream = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        stream.set_reader(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "NorwegianMinimalStem", &["variant", "nn"])?
                .create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["gut", "gut", "gut", "gut", "gut", "gut"])?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected = iae_message(|| {
            token_filter_factory(PKG, "NorwegianMinimalStem", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.no.TestNorwegianMinimalStemFilterFactory")
            .method(t("testStemming", test_stemming))
            .method(t("testBokmaalStemming", test_bokmaal_stemming))
            .method(t("testNynorskStemming", test_nynorsk_stemming))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

