// -----------------------------------------------------------------------------

mod test_norwegian_normalization_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::miscellaneous::scandinavian_normalization_filter::new_scandinavian_normalization_filter;
    use rucene_analysis_common::analysis::no::norwegian_normalization_filter::new_norwegian_normalization_filter;

    fn test_default() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = create_analyzer();
        B::check_one_term(&*analyzer, "ae\u{E4}aeeea", "\u{E6}\u{E6}\u{E6}eea")?;
        // should not cause ArrayIndexOutOfBoundsException
        B::check_one_term(&*analyzer, "ae\u{E4}aeeeae", "\u{E6}\u{E6}\u{E6}ee\u{E6}")?;
        B::check_one_term(&*analyzer, "aeaeeeae", "\u{E6}\u{E6}ee\u{E6}")?;
        B::check_one_term(&*analyzer, "b\u{F8}en", "b\u{F8}en")?;
        B::check_one_term(&*analyzer, "bOEen", "b\u{D8}en")?;
        B::check_one_term(&*analyzer, "\u{E5}ene", "\u{E5}ene")?;
        B::check_one_term(
            &*analyzer,
            "bl\u{E5}b\u{E6}rsyltet\u{F8}j",
            "bl\u{E5}b\u{E6}rsyltet\u{F8}j",
        )?;
        B::check_one_term(
            &*analyzer,
            "blaabaersyltet\u{F6}j",
            "bl\u{E5}b\u{E6}rsyltet\u{F8}j",
        )?;
        B::check_one_term(
            &*analyzer,
            "r\u{E4}ksm\u{F6}rg\u{E5}s",
            "r\u{E6}ksm\u{F8}rg\u{E5}s",
        )?;
        B::check_one_term(&*analyzer, "raeksm\u{F6}rgaas", "r\u{E6}ksm\u{F8}rg\u{E5}s")?;
        B::check_one_term(&*analyzer, "raeksmoerg\u{E5}s", "r\u{E6}ksm\u{F8}rg\u{E5}s")?;
        B::check_one_term(&*analyzer, "ab", "ab")?;
        B::check_one_term(&*analyzer, "ob", "ob")?;
        B::check_one_term(&*analyzer, "Ab", "Ab")?;
        B::check_one_term(&*analyzer, "Ob", "Ob")?;
        B::check_one_term(&*analyzer, "\u{E5}", "\u{E5}")?;
        B::check_one_term(&*analyzer, "aa", "\u{E5}")?;
        B::check_one_term(&*analyzer, "aA", "\u{E5}")?;
        B::check_one_term(&*analyzer, "ao", "ao")?;
        B::check_one_term(&*analyzer, "aO", "aO")?;
        B::check_one_term(&*analyzer, "AA", "\u{C5}")?;
        B::check_one_term(&*analyzer, "Aa", "\u{C5}")?;
        B::check_one_term(&*analyzer, "Ao", "Ao")?;
        B::check_one_term(&*analyzer, "AO", "AO")?;
        B::check_one_term(&*analyzer, "\u{E6}", "\u{E6}")?;
        B::check_one_term(&*analyzer, "\u{E4}", "\u{E6}")?;
        B::check_one_term(&*analyzer, "\u{C6}", "\u{C6}")?;
        B::check_one_term(&*analyzer, "\u{C4}", "\u{C6}")?;
        B::check_one_term(&*analyzer, "ae", "\u{E6}")?;
        B::check_one_term(&*analyzer, "aE", "\u{E6}")?;
        B::check_one_term(&*analyzer, "Ae", "\u{C6}")?;
        B::check_one_term(&*analyzer, "AE", "\u{C6}")?;
        B::check_one_term(&*analyzer, "\u{F6}", "\u{F8}")?;
        B::check_one_term(&*analyzer, "\u{F8}", "\u{F8}")?;
        B::check_one_term(&*analyzer, "\u{D6}", "\u{D8}")?;
        B::check_one_term(&*analyzer, "\u{D8}", "\u{D8}")?;
        B::check_one_term(&*analyzer, "oo", "oo")?;
        B::check_one_term(&*analyzer, "oe", "\u{F8}")?;
        B::check_one_term(&*analyzer, "oO", "oO")?;
        B::check_one_term(&*analyzer, "oE", "\u{F8}")?;
        B::check_one_term(&*analyzer, "Oo", "Oo")?;
        B::check_one_term(&*analyzer, "Oe", "\u{D8}")?;
        B::check_one_term(&*analyzer, "OO", "OO")?;
        B::check_one_term(&*analyzer, "OE", "\u{D8}")?;
        analyzer.close();
        Ok(())
    }

    /// check that the empty string doesn't cause issues
    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.no.TestNorwegianNormalizationFilter$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_scandinavian_normalization_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_data() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = create_analyzer();
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    fn create_analyzer() -> Arc<dyn Analyzer> {
        FnAnalyzer::new(
            "org.apache.lucene.analysis.no.TestNorwegianNormalizationFilter$2",
            move |_| {
                let tokenizer = own(MockTokenizer::new(Arc::clone(&WHITESPACE), false)?);
                let stream = boxed(new_norwegian_normalization_filter(shared(&tokenizer))?);
                let stream = stream;
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc()
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.no.TestNorwegianNormalizationFilter")
            .method(t("testDefault", test_default))
            .method(t("testEmptyTerm", test_empty_term))
            .method(t("testRandomData", test_random_data))
            .build()
    }
}

