mod test_portuguese_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::pt::portuguese_analyzer::PortugueseAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        PortugueseAnalyzer::new().close();
        Ok(())
    }

    /// test stopwords and stemming
    fn test_basics() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(PortugueseAnalyzer::new());
        // stemming
        B::check_one_term(&*a, "quilom\u{E9}tricas", "quilometric")?;
        B::check_one_term(&*a, "quilom\u{E9}tricos", "quilometric")?;
        // stopword
        B::assert_analyzes_to(&*a, "n\u{E3}o", &[])?;
        a.close();
        Ok(())
    }

    /// test use of exclusion set
    fn test_exclude() -> Result<()> {
        let exclusion_set = char_set(&["quilom\u{E9}tricas"], false);
        let a: Arc<dyn Analyzer> = Arc::new(PortugueseAnalyzer::with_stem_exclusion_set(
            PortugueseAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(&*a, "quilom\u{E9}tricas", "quilom\u{E9}tricas")?;
        B::check_one_term(&*a, "quilom\u{E9}tricos", "quilometric")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(PortugueseAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.pt.TestPortugueseAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasics", test_basics))
            .method(t("testExclude", test_exclude))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

