mod test_spanish_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::es::spanish_analyzer::SpanishAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        SpanishAnalyzer::new().close();
        Ok(())
    }

    /// test stopwords and stemming
    fn test_basics() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(SpanishAnalyzer::new());
        // stemming
        B::check_one_term(&*a, "chicana", "chican")?;
        B::check_one_term(&*a, "chicano", "chican")?;
        // stopword
        B::assert_analyzes_to(&*a, "los", &[])?;
        a.close();
        Ok(())
    }

    /// test use of exclusion set
    fn test_exclude() -> Result<()> {
        let exclusion_set = char_set(&["chicano"], false);
        let a: Arc<dyn Analyzer> = Arc::new(SpanishAnalyzer::with_stem_exclusion_set(
            SpanishAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(&*a, "chicana", "chican")?;
        B::check_one_term(&*a, "chicano", "chicano")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(SpanishAnalyzer::new());
        B::check_random_data(&*random(), &a, 200 * mult())?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.es.TestSpanishAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasics", test_basics))
            .method(t("testExclude", test_exclude))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

