mod test_swedish_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::sv::swedish_analyzer::SwedishAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        SwedishAnalyzer::new().close();
        Ok(())
    }

    /// test stopwords and stemming
    fn test_basics() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(SwedishAnalyzer::new());
        // stemming
        B::check_one_term(&*a, "jaktkarlarne", "jaktkarl")?;
        B::check_one_term(&*a, "jaktkarlens", "jaktkarl")?;
        // stopword
        B::assert_analyzes_to(&*a, "och", &[])?;
        a.close();
        Ok(())
    }

    /// test use of exclusion set
    fn test_exclude() -> Result<()> {
        let exclusion_set = char_set(&["jaktkarlarne"], false);
        let a: Arc<dyn Analyzer> = Arc::new(SwedishAnalyzer::with_stem_exclusion_set(
            SwedishAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(&*a, "jaktkarlarne", "jaktkarlarne")?;
        B::check_one_term(&*a, "jaktkarlens", "jaktkarl")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(SwedishAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.sv.TestSwedishAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasics", test_basics))
            .method(t("testExclude", test_exclude))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

