mod test_indonesian_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::id::indonesian_analyzer::IndonesianAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        IndonesianAnalyzer::new().close();
        Ok(())
    }

    /// test stopwords and stemming
    fn test_basics() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(IndonesianAnalyzer::new());
        // stemming
        B::check_one_term(&*a, "peledakan", "ledak")?;
        B::check_one_term(&*a, "pembunuhan", "bunuh")?;
        // stopword
        B::assert_analyzes_to(&*a, "bahwa", &[])?;
        a.close();
        Ok(())
    }

    /// test use of exclusion set
    fn test_exclude() -> Result<()> {
        let exclusion_set = char_set(&["peledakan"], false);
        let a: Arc<dyn Analyzer> = Arc::new(IndonesianAnalyzer::with_stem_exclusion_set(
            IndonesianAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(&*a, "peledakan", "peledakan")?;
        B::check_one_term(&*a, "pembunuhan", "bunuh")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(IndonesianAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.id.TestIndonesianAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasics", test_basics))
            .method(t("testExclude", test_exclude))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

