fn test_indonesian_analyzer() {
    run(test_indonesian_analyzer::class);
}

// -----------------------------------------------------------------------------
// TestIndonesianStemFilterFactory
// -----------------------------------------------------------------------------

mod test_indonesian_stem_filter_factory {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.id";

    /// Ensure the filter actually stems text.
    fn test_stemming() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new("dibukukannya"));
        let mut stream = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        stream.set_reader(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndonesianStem", &[])?.create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["buku"])?;
        Ok(())
    }

    /// Test inflectional-only mode
    fn test_stemming_inflectional() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new("dibukukannya"));
        let mut stream = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        stream.set_reader(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndonesianStem", &["stemDerivational", "false"])?
                .create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["dibukukan"])?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected = iae_message(|| {
            token_filter_factory(PKG, "IndonesianStem", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.id.TestIndonesianStemFilterFactory")
            .method(t("testStemming", test_stemming))
            .method(t("testStemmingInflectional", test_stemming_inflectional))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

#[test]
fn test_indonesian_stem_filter_factory() {
    run(test_indonesian_stem_filter_factory::class);
}

