        // stemming
        B::check_one_term(&*a, "siopad\u{F3}ireacht", "siopad\u{F3}ir")?;
        B::check_one_term(&*a, "s\u{ED}ceapatacha", "s\u{ED}ceapaite")?;
        // stopword
        B::assert_analyzes_to(&*a, "le", &[])?;
        a.close();
        Ok(())
