    fn test_contractions() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(IrishAnalyzer::new());
        B::assert_analyzes_to(&*a, "b'fhearr m'athair", &["fearr", "athair"])?;
        a.close();
        Ok(())
    }

    /// test use of exclusion set
    fn test_exclude() -> Result<()> {
        let exclusion_set = char_set(&["feirmeoireacht"], false);
        let a: Arc<dyn Analyzer> = Arc::new(IrishAnalyzer::with_stem_exclusion_set(
            IrishAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(&*a, "feirmeoireacht", "feirmeoireacht")?;
        B::check_one_term(&*a, "siopad\u{F3}ireacht", "siopad\u{F3}ir")?;
        a.close();
        Ok(())
    }

    /// test special hyphen handling
    fn test_hyphens() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(IrishAnalyzer::new());
        B::assert_analyzes_to_pos_increments(&*a, "n-athair", &["athair"], &[2])?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(IrishAnalyzer::new());
        B::check_random_data(&*random(), &a, 200 * mult())?;
        a.close();
        Ok(())
    }

