// -----------------------------------------------------------------------------
// TestRomanianNormalizationFilter
// -----------------------------------------------------------------------------

mod test_romanian_normalization_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::ro::romanian_normalization_filter::new_romanian_normalization_filter;

    thread_local! {
        /// The `a` field.
        static A: RefCell<Option<Arc<dyn Analyzer>>> = const { RefCell::new(None) };
    }
    fn a() -> Arc<dyn Analyzer> {
        A.with(|f| Arc::clone(f.borrow().as_ref().expect("setUp")))
    }
    fn set_a(a: Arc<dyn Analyzer>) {
        A.with(|f| *f.borrow_mut() = Some(a));
    }

    fn set_up() -> Result<()> {
        LuceneTestCase::super_set_up();
        set_a(
            FnAnalyzer::new(
                "org.apache.lucene.analysis.ro.TestRomanianNormalizationFilter$1",
                move |_| {
                    let tokenizer = own(MockTokenizer::new(Arc::clone(&WHITESPACE), false)?);
                    let stream = boxed(new_romanian_normalization_filter(shared(&tokenizer))?);
                    Ok(components(
                        tokenizer,
                        rucene_test_framework::analysis::sink(BoxedStream(stream)),
                    ))
                },
            )
            .arc(),
        );
        Ok(())
    }

    fn tear_down() -> Result<()> {
        a().close();
        LuceneTestCase::super_tear_down();
        Ok(())
    }

    fn test_small_s_cedilla() -> Result<()> {
        B::check_one_term(&*a(), "ace\u{15F}ti", "ace\u{219}ti")?;
        Ok(())
    }

    fn test_capital_s_cedilla() -> Result<()> {
        B::check_one_term(&*a(), "ACE\u{15E}TI", "ACE\u{218}TI")?;
        Ok(())
    }

    fn test_small_t_cedilla() -> Result<()> {
        B::check_one_term(&*a(), "c\u{E2}\u{163}i", "c\u{E2}\u{21B}i")?;
        Ok(())
    }

    fn test_capital_t_cedilla() -> Result<()> {
        B::check_one_term(&*a(), "C\u{C2}\u{162}I", "C\u{C2}\u{21A}I")?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.ro.TestRomanianNormalizationFilter$2",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_romanian_normalization_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.ro.TestRomanianNormalizationFilter")
            .method(hook("setUp", set_up))
            .method(hook("tearDown", tear_down))
            .method(t("testSmallSCedilla", test_small_s_cedilla))
            .method(t("testCapitalSCedilla", test_capital_s_cedilla))
            .method(t("testSmallTCedilla", test_small_t_cedilla))
            .method(t("testCapitalTCedilla", test_capital_t_cedilla))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

