// -----------------------------------------------------------------------------
// TestTurkishLowerCaseFilter
// -----------------------------------------------------------------------------

mod test_turkish_lower_case_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::tr::turkish_lower_case_filter::new_turkish_lower_case_filter;

    /// Test composed forms
    fn test_turkish_lower_case_filter() -> Result<()> {
        let stream = B::whitespace_mock_tokenizer_str("\u{130}STANBUL \u{130}ZM\u{130}R ISPARTA")?;
        let mut filter: Box<dyn TokenStream> = boxed(new_turkish_lower_case_filter(boxed(stream))?);
        B::assert_token_stream_contents(&mut *filter, &["istanbul", "izmir", "\u{131}sparta"])?;
        Ok(())
    }

    /// Test decomposed forms
    fn test_decomposed() -> Result<()> {
        let stream =
            B::whitespace_mock_tokenizer_str("I\u{307}STANBUL I\u{307}ZMI\u{307}R ISPARTA")?;
        let mut filter: Box<dyn TokenStream> = boxed(new_turkish_lower_case_filter(boxed(stream))?);
        B::assert_token_stream_contents(&mut *filter, &["istanbul", "izmir", "\u{131}sparta"])?;
        Ok(())
    }

    /// Test decomposed forms with additional accents In this example, U+0049 + U+0316 + U+0307 is
    /// canonically equivalent to U+0130 + U+0316, and is lowercased the same way.
    fn test_decomposed2() -> Result<()> {
        let stream = B::whitespace_mock_tokenizer_str(
            "I\u{316}\u{307}STANBUL I\u{307}ZMI\u{307}R I\u{316}SPARTA",
        )?;
        let mut filter: Box<dyn TokenStream> = boxed(new_turkish_lower_case_filter(boxed(stream))?);
        B::assert_token_stream_contents(
            &mut *filter,
            &["i\u{316}stanbul", "izmir", "\u{131}\u{316}sparta"],
        )?;
        Ok(())
    }

    fn test_decomposed3() -> Result<()> {
        let stream = B::whitespace_mock_tokenizer_str("I\u{307}")?;
        let mut filter: Box<dyn TokenStream> = boxed(new_turkish_lower_case_filter(boxed(stream))?);
        B::assert_token_stream_contents(&mut *filter, &["i"])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.tr.TestTurkishLowerCaseFilter$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_turkish_lower_case_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.tr.TestTurkishLowerCaseFilter")
            .method(t(
                "testTurkishLowerCaseFilter",
                test_turkish_lower_case_filter,
            ))
            .method(t("testDecomposed", test_decomposed))
            .method(t("testDecomposed2", test_decomposed2))
            .method(t("testDecomposed3", test_decomposed3))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

