// -----------------------------------------------------------------------------
// TestBulgarianStemFilterFactory
// -----------------------------------------------------------------------------

mod test_bulgarian_stem_filter_factory {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.bg";

    /// Ensure the filter actually stems text.
    fn test_stemming() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new(
            "\u{43A}\u{43E}\u{43C}\u{43F}\u{44E}\u{442}\u{440}\u{438}",
        ));
        let tokenizer = B::whitespace_mock_tokenizer(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "BulgarianStem", &[])?.create(boxed(tokenizer))?;
        B::assert_token_stream_contents(
            &mut *stream,
            &["\u{43A}\u{43E}\u{43C}\u{43F}\u{44E}\u{442}\u{440}"],
        )?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected =
            iae_message(|| token_filter_factory(PKG, "BulgarianStem", &["bogusArg", "bogusValue"]));
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.bg.TestBulgarianStemFilterFactory")
            .method(t("testStemming", test_stemming))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

