// TestCzechStemmer
// -----------------------------------------------------------------------------

mod test_czech_stemmer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::cz::czech_analyzer::CzechAnalyzer;
    use rucene_analysis_common::analysis::cz::czech_stem_filter::new_czech_stem_filter;
    use rucene_analysis_common::analysis::miscellaneous::set_keyword_marker_filter::new_set_keyword_marker_filter;

    /// Test showing how masculine noun forms conflate
    fn test_masculine_nouns() -> Result<()> {
        let cz: Arc<dyn Analyzer> = Arc::new(CzechAnalyzer::new());
        B::assert_analyzes_to(&*cz, "p\u{E1}n", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}ni", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}nov\u{E9}", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}na", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}n\u{16F}", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}novi", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}n\u{16F}m", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}ny", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}ne", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}nech", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "p\u{E1}nem", &["p\u{E1}n"])?;
        B::assert_analyzes_to(&*cz, "hrad", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "hradu", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "hrade", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "hradem", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "hrady", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "hradech", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "hrad\u{16F}m", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "hrad\u{16F}", &["hrad"])?;
        B::assert_analyzes_to(&*cz, "mu\u{17E}", &["muh"])?;
        B::assert_analyzes_to(&*cz, "mu\u{17E}i", &["muh"])?;
        B::assert_analyzes_to(&*cz, "mu\u{17E}e", &["muh"])?;
        B::assert_analyzes_to(&*cz, "mu\u{17E}\u{16F}", &["muh"])?;
        B::assert_analyzes_to(&*cz, "mu\u{17E}\u{16F}m", &["muh"])?;
        B::assert_analyzes_to(&*cz, "mu\u{17E}\u{ED}ch", &["muh"])?;
        B::assert_analyzes_to(&*cz, "mu\u{17E}em", &["muh"])?;
        B::assert_analyzes_to(&*cz, "stroj", &["stroj"])?;
        B::assert_analyzes_to(&*cz, "stroje", &["stroj"])?;
        B::assert_analyzes_to(&*cz, "stroj\u{16F}", &["stroj"])?;
        B::assert_analyzes_to(&*cz, "stroji", &["stroj"])?;
        B::assert_analyzes_to(&*cz, "stroj\u{16F}m", &["stroj"])?;
        B::assert_analyzes_to(&*cz, "stroj\u{ED}ch", &["stroj"])?;
        B::assert_analyzes_to(&*cz, "strojem", &["stroj"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edseda", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsedov\u{E9}", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsedy", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsed\u{16F}", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsedovi", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsed\u{16F}m", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsedu", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsedo", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsedech", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "p\u{159}edsedou", &["p\u{159}edsd"])?;
        B::assert_analyzes_to(&*cz, "soudce", &["soudk"])?;
        B::assert_analyzes_to(&*cz, "soudci", &["soudk"])?;
        B::assert_analyzes_to(&*cz, "soudc\u{16F}", &["soudk"])?;
        B::assert_analyzes_to(&*cz, "soudc\u{16F}m", &["soudk"])?;
        B::assert_analyzes_to(&*cz, "soudc\u{ED}ch", &["soudk"])?;
        B::assert_analyzes_to(&*cz, "soudcem", &["soudk"])?;
        cz.close();
        Ok(())
    }

    /// Test showing how feminine noun forms conflate
    fn test_feminine_nouns() -> Result<()> {
        let cz: Arc<dyn Analyzer> = Arc::new(CzechAnalyzer::new());
        B::assert_analyzes_to(&*cz, "kost", &["kost"])?;
        B::assert_analyzes_to(&*cz, "kosti", &["kost"])?;
        B::assert_analyzes_to(&*cz, "kost\u{ED}", &["kost"])?;
        B::assert_analyzes_to(&*cz, "kostem", &["kost"])?;
        B::assert_analyzes_to(&*cz, "kostech", &["kost"])?;
        B::assert_analyzes_to(&*cz, "kostmi", &["kost"])?;
        // note: in this example sing nom. and sing acc. don't conflate w/ the rest
        B::assert_analyzes_to(&*cz, "p\u{ED}se\u{148}", &["p\u{ED}s\u{148}"])?;
        B::assert_analyzes_to(&*cz, "p\u{ED}sn\u{11B}", &["p\u{ED}sn"])?;
        B::assert_analyzes_to(&*cz, "p\u{ED}sni", &["p\u{ED}sn"])?;
        B::assert_analyzes_to(&*cz, "p\u{ED}sn\u{11B}mi", &["p\u{ED}sn"])?;
        B::assert_analyzes_to(&*cz, "p\u{ED}sn\u{ED}ch", &["p\u{ED}sn"])?;
        B::assert_analyzes_to(&*cz, "p\u{ED}sn\u{ED}m", &["p\u{ED}sn"])?;
        B::assert_analyzes_to(&*cz, "r\u{16F}\u{17E}e", &["r\u{16F}h"])?;
        B::assert_analyzes_to(&*cz, "r\u{16F}\u{17E}\u{ED}", &["r\u{16F}h"])?;
        B::assert_analyzes_to(&*cz, "r\u{16F}\u{17E}\u{ED}m", &["r\u{16F}h"])?;
        B::assert_analyzes_to(&*cz, "r\u{16F}\u{17E}\u{ED}ch", &["r\u{16F}h"])?;
        B::assert_analyzes_to(&*cz, "r\u{16F}\u{17E}emi", &["r\u{16F}h"])?;
        B::assert_analyzes_to(&*cz, "r\u{16F}\u{17E}i", &["r\u{16F}h"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}ena", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}eny", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}en", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}en\u{11B}", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}en\u{E1}m", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}enu", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}eno", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}en\u{E1}ch", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}enou", &["\u{17E}n"])?;
        B::assert_analyzes_to(&*cz, "\u{17E}enami", &["\u{17E}n"])?;
        cz.close();
        Ok(())
    }

    /// Test showing how neuter noun forms conflate
    fn test_neuter_nouns() -> Result<()> {
        let cz: Arc<dyn Analyzer> = Arc::new(CzechAnalyzer::new());
        B::assert_analyzes_to(&*cz, "m\u{11B}sto", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}sta", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}st", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}stu", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}st\u{16F}m", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}st\u{11B}", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}stech", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}stem", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "m\u{11B}sty", &["m\u{11B}st"])?;
        B::assert_analyzes_to(&*cz, "mo\u{159}e", &["mo\u{159}"])?;
        B::assert_analyzes_to(&*cz, "mo\u{159}\u{ED}", &["mo\u{159}"])?;
        B::assert_analyzes_to(&*cz, "mo\u{159}\u{ED}m", &["mo\u{159}"])?;
        B::assert_analyzes_to(&*cz, "mo\u{159}i", &["mo\u{159}"])?;
        B::assert_analyzes_to(&*cz, "mo\u{159}\u{ED}ch", &["mo\u{159}"])?;
        B::assert_analyzes_to(&*cz, "mo\u{159}em", &["mo\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}e", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}ata", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}ete", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}at", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}eti", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}at\u{16F}m", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}atech", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}etem", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "ku\u{159}aty", &["ku\u{159}"])?;
        B::assert_analyzes_to(&*cz, "staven\u{ED}", &["stavn"])?;
        B::assert_analyzes_to(&*cz, "staven\u{ED}m", &["stavn"])?;
        B::assert_analyzes_to(&*cz, "staven\u{ED}ch", &["stavn"])?;
        B::assert_analyzes_to(&*cz, "staven\u{ED}mi", &["stavn"])?;
        cz.close();
        Ok(())
    }

    /// Test showing how adjectival forms conflate
    fn test_adjectives() -> Result<()> {
        let cz: Arc<dyn Analyzer> = Arc::new(CzechAnalyzer::new());
        B::assert_analyzes_to(&*cz, "mlad\u{FD}", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{ED}", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{E9}ho", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{FD}ch", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{E9}mu", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{FD}m", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{E9}", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{E9}m", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{FD}mi", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mlad\u{E1}", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "mladou", &["mlad"])?;
        B::assert_analyzes_to(&*cz, "jarn\u{ED}", &["jarn"])?;
        B::assert_analyzes_to(&*cz, "jarn\u{ED}ho", &["jarn"])?;
        B::assert_analyzes_to(&*cz, "jarn\u{ED}ch", &["jarn"])?;
        B::assert_analyzes_to(&*cz, "jarn\u{ED}mu", &["jarn"])?;
        B::assert_analyzes_to(&*cz, "jarn\u{ED}m", &["jarn"])?;
        B::assert_analyzes_to(&*cz, "jarn\u{ED}mi", &["jarn"])?;
        cz.close();
        Ok(())
    }

    /// Test some possessive suffixes
    fn test_possessive() -> Result<()> {
        let cz: Arc<dyn Analyzer> = Arc::new(CzechAnalyzer::new());
        B::assert_analyzes_to(&*cz, "Karl\u{16F}v", &["karl"])?;
        B::assert_analyzes_to(&*cz, "jazykov\u{FD}", &["jazyk"])?;
        cz.close();
        Ok(())
    }

    /// Test some exceptional rules, implemented as rewrites.
    fn test_exceptions() -> Result<()> {
        let cz: Arc<dyn Analyzer> = Arc::new(CzechAnalyzer::new());
        B::assert_analyzes_to(&*cz, "\u{10D}esk\u{FD}", &["\u{10D}esk"])?;
        B::assert_analyzes_to(&*cz, "\u{10D}e\u{161}t\u{ED}", &["\u{10D}esk"])?;
        B::assert_analyzes_to(&*cz, "anglick\u{FD}", &["anglick"])?;
        B::assert_analyzes_to(&*cz, "angli\u{10D}t\u{ED}", &["anglick"])?;
        B::assert_analyzes_to(&*cz, "kniha", &["knih"])?;
        B::assert_analyzes_to(&*cz, "knize", &["knih"])?;
        B::assert_analyzes_to(&*cz, "mazat", &["mah"])?;
        B::assert_analyzes_to(&*cz, "ma\u{17E}u", &["mah"])?;
        B::assert_analyzes_to(&*cz, "kluk", &["kluk"])?;
        B::assert_analyzes_to(&*cz, "kluci", &["kluk"])?;
        B::assert_analyzes_to(&*cz, "kluc\u{ED}ch", &["kluk"])?;
        B::assert_analyzes_to(&*cz, "hezk\u{FD}", &["hezk"])?;
        B::assert_analyzes_to(&*cz, "hez\u{10D}\u{ED}", &["hezk"])?;
        B::assert_analyzes_to(&*cz, "h\u{16F}l", &["hol"])?;
        B::assert_analyzes_to(&*cz, "hole", &["hol"])?;
        B::assert_analyzes_to(&*cz, "deska", &["desk"])?;
        B::assert_analyzes_to(&*cz, "desek", &["desk"])?;
        cz.close();
        Ok(())
    }

    /// Test that very short words are not stemmed.
    fn test_dont_stem() -> Result<()> {
        let cz: Arc<dyn Analyzer> = Arc::new(CzechAnalyzer::new());
        B::assert_analyzes_to(&*cz, "e", &["e"])?;
        B::assert_analyzes_to(&*cz, "zi", &["zi"])?;
        cz.close();
        Ok(())
    }

    fn test_with_keyword_attribute() -> Result<()> {
        let mut set = CharArraySet::new(1, true);
        set.add("hole");
        let mut in_ = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        in_.set_reader(Box::new(StringCharReader::new("hole desek")))?;
        let mut filter: Box<dyn TokenStream> = boxed(new_czech_stem_filter(boxed(
            new_set_keyword_marker_filter(boxed(in_), set.clone())?,
        ))?);
        B::assert_token_stream_contents(&mut *filter, &["hole", "desk"])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.cz.TestCzechStemmer$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_czech_stem_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.cz.TestCzechStemmer")
            .method(t("testMasculineNouns", test_masculine_nouns))
            .method(t("testFeminineNouns", test_feminine_nouns))
            .method(t("testNeuterNouns", test_neuter_nouns))
            .method(t("testAdjectives", test_adjectives))
            .method(t("testPossessive", test_possessive))
            .method(t("testExceptions", test_exceptions))
            .method(t("testDontStem", test_dont_stem))
            .method(t("testWithKeywordAttribute", test_with_keyword_attribute))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

#[test]
fn test_czech_stemmer() {
    run(test_czech_stemmer::class);
}

