// -----------------------------------------------------------------------------
// TestFinnishLightStemFilter
// -----------------------------------------------------------------------------

mod test_finnish_light_stem_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::fi::finnish_light_stem_filter::new_finnish_light_stem_filter;
    use rucene_analysis_common::analysis::miscellaneous::set_keyword_marker_filter::new_set_keyword_marker_filter;

    const PKG: &str = "org.apache.lucene.analysis.fi";

    thread_local! {
        /// The `analyzer` field.
        static ANALYZER: RefCell<Option<Arc<dyn Analyzer>>> = const { RefCell::new(None) };
    }
    fn analyzer() -> Arc<dyn Analyzer> {
        ANALYZER.with(|f| Arc::clone(f.borrow().as_ref().expect("setUp")))
    }
    fn set_analyzer(a: Arc<dyn Analyzer>) {
        ANALYZER.with(|f| *f.borrow_mut() = Some(a));
    }

    fn set_up() -> Result<()> {
        LuceneTestCase::super_set_up();
        set_analyzer(
            FnAnalyzer::new(
                "org.apache.lucene.analysis.fi.TestFinnishLightStemFilter$1",
                move |_| {
                    let source = own(MockTokenizer::new(Arc::clone(&WHITESPACE), false)?);
                    let stream = boxed(new_finnish_light_stem_filter(shared(&source))?);
                    Ok(components(
                        source,
                        rucene_test_framework::analysis::sink(BoxedStream(stream)),
                    ))
                },
            )
            .arc(),
        );
        Ok(())
    }

    fn tear_down() -> Result<()> {
        analyzer().close();
        LuceneTestCase::super_tear_down();
        Ok(())
    }

    /// Test against a vocabulary from the reference impl
    fn test_vocabulary() -> Result<()> {
        VocabularyAssert::assert_vocabulary_zip_tsv(
            &*analyzer(),
            &data_path(PKG, "filighttestdata.zip")?,
            "filight.txt",
        )?;
        Ok(())
    }

    fn test_keyword() -> Result<()> {
        let exclusion_set = char_set(&["edelt\u{E4}jist\u{E4}\u{E4}n"], false);
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.fi.TestFinnishLightStemFilter$2",
            move |_| {
                let source = own(MockTokenizer::new(Arc::clone(&WHITESPACE), false)?);
                let sink = boxed(new_set_keyword_marker_filter(
                    shared(&source),
                    exclusion_set.clone(),
                )?);
                let stream = boxed(new_finnish_light_stem_filter(sink)?);
                Ok(components(
                    source,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(
            &*a,
            "edelt\u{E4}jist\u{E4}\u{E4}n",
            "edelt\u{E4}jist\u{E4}\u{E4}n",
        )?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        B::check_random_data(&*random(), &analyzer(), 200 * mult())?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.fi.TestFinnishLightStemFilter$3",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_finnish_light_stem_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.fi.TestFinnishLightStemFilter")
            .method(hook("setUp", set_up))
            .method(hook("tearDown", tear_down))
            .method(t("testVocabulary", test_vocabulary))
            .method(t("testKeyword", test_keyword))
            .method(t("testRandomStrings", test_random_strings))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

#[test]
fn test_finnish_light_stem_filter() {
    run(test_finnish_light_stem_filter::class);
}

