    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        LithuanianAnalyzer::new().close();
        Ok(())
    }

    /// Test stopword removal
    fn test_stop_word() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(LithuanianAnalyzer::new());
        B::assert_analyzes_to(&*a, "man", &[])?;
        Ok(())
    }

