    fn test_stem_exclusion() -> Result<()> {
        let mut set = CharArraySet::new(1, true);
        set.add("vaik\u{173}");
        let a: Arc<dyn Analyzer> = Arc::new(LithuanianAnalyzer::with_stem_exclusion_set(
            CharArraySet::empty_set(),
            &set,
        ));
        B::assert_analyzes_to(&*a, "vaik\u{173}", &["vaik\u{173}"])?;
        Ok(())
    }

