mod test_russian_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::ru::russian_analyzer::RussianAnalyzer;

    /// Check that RussianAnalyzer doesnt discard any numbers
    fn test_digits_in_russian_charset() -> Result<()> {
        let ra: Arc<dyn Analyzer> = Arc::new(RussianAnalyzer::new());
        B::assert_analyzes_to(&*ra, "text 1000", &["text", "1000"])?;
        ra.close();
        Ok(())
    }

    fn test_reusable_token_stream() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(RussianAnalyzer::new());
        B::assert_analyzes_to(&*a, "\u{412}\u{43C}\u{435}\u{441}\u{442}\u{435} \u{441} \u{442}\u{435}\u{43C} \u{43E} \u{441}\u{438}\u{43B}\u{435} \u{44D}\u{43B}\u{435}\u{43A}\u{442}\u{440}\u{43E}\u{43C}\u{430}\u{433}\u{43D}\u{438}\u{442}\u{43D}\u{43E}\u{439} \u{44D}\u{43D}\u{435}\u{440}\u{433}\u{438}\u{438} \u{438}\u{43C}\u{435}\u{43B}\u{438} \u{43F}\u{440}\u{435}\u{434}\u{441}\u{442}\u{430}\u{432}\u{43B}\u{435}\u{43D}\u{438}\u{435} \u{435}\u{449}\u{435}", &["\u{432}\u{43C}\u{435}\u{441}\u{442}", "\u{441}\u{438}\u{43B}", "\u{44D}\u{43B}\u{435}\u{43A}\u{442}\u{440}\u{43E}\u{43C}\u{430}\u{433}\u{43D}\u{438}\u{442}\u{43D}", "\u{44D}\u{43D}\u{435}\u{440}\u{433}", "\u{438}\u{43C}\u{435}\u{43B}", "\u{43F}\u{440}\u{435}\u{434}\u{441}\u{442}\u{430}\u{432}\u{43B}\u{435}\u{43D}"])?;
        B::assert_analyzes_to(&*a, "\u{41D}\u{43E} \u{437}\u{43D}\u{430}\u{43D}\u{438}\u{435} \u{44D}\u{442}\u{43E} \u{445}\u{440}\u{430}\u{43D}\u{438}\u{43B}\u{43E}\u{441}\u{44C} \u{432} \u{442}\u{430}\u{439}\u{43D}\u{435}", &["\u{437}\u{43D}\u{430}\u{43D}", "\u{44D}\u{442}", "\u{445}\u{440}\u{430}\u{43D}", "\u{442}\u{430}\u{439}\u{43D}"])?;
        a.close();
        Ok(())
    }

    fn test_with_stem_exclusion_set() -> Result<()> {
        let mut set = CharArraySet::new(1, true);
        set.add("\u{43F}\u{440}\u{435}\u{434}\u{441}\u{442}\u{430}\u{432}\u{43B}\u{435}\u{43D}\u{438}\u{435}");
        let a: Arc<dyn Analyzer> = Arc::new(RussianAnalyzer::with_stem_exclusion_set(
            RussianAnalyzer::get_default_stop_set().clone(),
            &set,
        ));
        B::assert_analyzes_to(&*a, "\u{412}\u{43C}\u{435}\u{441}\u{442}\u{435} \u{441} \u{442}\u{435}\u{43C} \u{43E} \u{441}\u{438}\u{43B}\u{435} \u{44D}\u{43B}\u{435}\u{43A}\u{442}\u{440}\u{43E}\u{43C}\u{430}\u{433}\u{43D}\u{438}\u{442}\u{43D}\u{43E}\u{439} \u{44D}\u{43D}\u{435}\u{440}\u{433}\u{438}\u{438} \u{438}\u{43C}\u{435}\u{43B}\u{438} \u{43F}\u{440}\u{435}\u{434}\u{441}\u{442}\u{430}\u{432}\u{43B}\u{435}\u{43D}\u{438}\u{435} \u{435}\u{449}\u{435}", &["\u{432}\u{43C}\u{435}\u{441}\u{442}", "\u{441}\u{438}\u{43B}", "\u{44D}\u{43B}\u{435}\u{43A}\u{442}\u{440}\u{43E}\u{43C}\u{430}\u{433}\u{43D}\u{438}\u{442}\u{43D}", "\u{44D}\u{43D}\u{435}\u{440}\u{433}", "\u{438}\u{43C}\u{435}\u{43B}", "\u{43F}\u{440}\u{435}\u{434}\u{441}\u{442}\u{430}\u{432}\u{43B}\u{435}\u{43D}\u{438}\u{435}"])?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(RussianAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.ru.TestRussianAnalyzer")
            .method(t(
                "testDigitsInRussianCharset",
                test_digits_in_russian_charset,
            ))
            .method(t("testReusableTokenStream", test_reusable_token_stream))
            .method(t("testWithStemExclusionSet", test_with_stem_exclusion_set))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

