mod test_serbian_normalization_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::sr::serbian_normalization_filter::new_serbian_normalization_filter;

    thread_local! {
        /// The `analyzer` field.
        static ANALYZER: RefCell<Option<Arc<dyn Analyzer>>> = const { RefCell::new(None) };
    }
    fn analyzer() -> Arc<dyn Analyzer> {
        ANALYZER.with(|f| Arc::clone(f.borrow().as_ref().expect("setUp")))
    }
    fn set_analyzer(a: Arc<dyn Analyzer>) {
        ANALYZER.with(|f| *f.borrow_mut() = Some(a));
    }

    fn set_up() -> Result<()> {
        LuceneTestCase::super_set_up();
        set_analyzer(
            FnAnalyzer::new(
                "org.apache.lucene.analysis.sr.TestSerbianNormalizationFilter$1",
                move |_| {
                    let tokenizer = own(MockTokenizer::new(Arc::clone(&WHITESPACE), false)?);
                    let stream = boxed(new_serbian_normalization_filter(shared(&tokenizer))?);
                    let stream = stream;
                    Ok(components(
                        tokenizer,
                        rucene_test_framework::analysis::sink(BoxedStream(stream)),
                    ))
                },
            )
            .arc(),
        );
        Ok(())
    }

    fn tear_down() -> Result<()> {
        analyzer().close();
        LuceneTestCase::super_tear_down();
        Ok(())
    }

    /// Tests Cyrillic text.
    fn test_cyrillic() -> Result<()> {
        B::check_one_term(&*analyzer(), "\u{430}\u{431}\u{432}\u{433}\u{434}\u{452}\u{435}\u{436}\u{437}\u{438}\u{458}\u{43A}\u{43B}\u{459}\u{43C}\u{43D}\u{45A}\u{43E}\u{43F}\u{440}\u{441}\u{442}\u{45B}\u{443}\u{444}\u{445}\u{446}\u{447}\u{45F}\u{448}", "abvgddjezzijklljmnnjoprstcufhccdzs")?;
        Ok(())
    }

    /// Tests Latin text.
    fn test_latin() -> Result<()> {
        B::check_one_term(
            &*analyzer(),
            "abc\u{10D}\u{107}dd\u{17E}\u{111}efghijklljmnnjoprs\u{161}tuvz\u{17E}",
            "abcccddzdjefghijklljmnnjoprsstuvzz",
        )?;
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        B::check_random_data(&*random(), &analyzer(), 200 * mult())?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.sr.TestSerbianNormalizationFilter$2",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_serbian_normalization_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.sr.TestSerbianNormalizationFilter")
            .method(hook("setUp", set_up))
            .method(hook("tearDown", tear_down))
            .method(t("testCyrillic", test_cyrillic))
            .method(t("testLatin", test_latin))
            .method(t("testRandomStrings", test_random_strings))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

