fn test_serbian_normalization_filter() {
    run(test_serbian_normalization_filter::class);
}

// -----------------------------------------------------------------------------
// TestSerbianNormalizationFilterFactory
// -----------------------------------------------------------------------------

mod test_serbian_normalization_filter_factory {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.sr";

    fn test_stemming() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new("\u{111}ura"));
        let mut stream = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        stream.set_reader(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "SerbianNormalization", &[])?.create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["djura"])?;
        Ok(())
    }

    fn test_regular_stemming() -> Result<()> {
        let reader: Box<dyn CharReader> =
            Box::new(StringCharReader::new("\u{452}\u{443}\u{440}\u{430}"));
        let mut stream = MockTokenizer::new(Arc::clone(&WHITESPACE), false)?;
        stream.set_reader(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "SerbianNormalization", &["haircut", "regular"])?
                .create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["\u{111}ura"])?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected = iae_message(|| {
            token_filter_factory(PKG, "SerbianNormalization", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.sr.TestSerbianNormalizationFilterFactory")
            .method(t("testStemming", test_stemming))
            .method(t("testRegularStemming", test_regular_stemming))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

#[test]
fn test_serbian_normalization_filter_factory() {
    run(test_serbian_normalization_filter_factory::class);
}

