// -----------------------------------------------------------------------------
// TestArabicAnalyzer
// -----------------------------------------------------------------------------

mod test_arabic_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::ar::arabic_analyzer::ArabicAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        ArabicAnalyzer::new().close();
        Ok(())
    }

    /// Some simple tests showing some features of the analyzer, how some regular forms will conflate
    fn test_basic_features() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::new());
        B::assert_analyzes_to(
            &*a,
            "\u{643}\u{628}\u{64A}\u{631}",
            &["\u{643}\u{628}\u{64A}\u{631}"],
        )?;
        B::assert_analyzes_to(
            &*a,
            "\u{643}\u{628}\u{64A}\u{631}\u{629}",
            &["\u{643}\u{628}\u{64A}\u{631}"],
        )?;
        // feminine marker
        B::assert_analyzes_to(
            &*a,
            "\u{645}\u{634}\u{631}\u{648}\u{628}",
            &["\u{645}\u{634}\u{631}\u{648}\u{628}"],
        )?;
        B::assert_analyzes_to(
            &*a,
            "\u{645}\u{634}\u{631}\u{648}\u{628}\u{627}\u{62A}",
            &["\u{645}\u{634}\u{631}\u{648}\u{628}"],
        )?;
        // plural -at
        B::assert_analyzes_to(
            &*a,
            "\u{623}\u{645}\u{631}\u{64A}\u{643}\u{64A}\u{64A}\u{646}",
            &["\u{627}\u{645}\u{631}\u{64A}\u{643}"],
        )?;
        // plural -in
        B::assert_analyzes_to(
            &*a,
            "\u{627}\u{645}\u{631}\u{64A}\u{643}\u{64A}",
            &["\u{627}\u{645}\u{631}\u{64A}\u{643}"],
        )?;
        // singular with bare alif
        B::assert_analyzes_to(
            &*a,
            "\u{643}\u{62A}\u{627}\u{628}",
            &["\u{643}\u{62A}\u{627}\u{628}"],
        )?;
        B::assert_analyzes_to(
            &*a,
            "\u{627}\u{644}\u{643}\u{62A}\u{627}\u{628}",
            &["\u{643}\u{62A}\u{627}\u{628}"],
        )?;
        // definite article
        B::assert_analyzes_to(&*a, "\u{645}\u{627} \u{645}\u{644}\u{643}\u{62A} \u{623}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}", &["\u{645}\u{644}\u{643}\u{62A}", "\u{627}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}"])?;
        B::assert_analyzes_to(&*a, "\u{627}\u{644}\u{630}\u{64A}\u{646} \u{645}\u{644}\u{643}\u{62A} \u{623}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}", &["\u{645}\u{644}\u{643}\u{62A}", "\u{627}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}"])?;
        // stopwords
        a.close();
        Ok(())
    }

    /// Simple tests to show things are getting reset correctly, etc.
    fn test_reusable_token_stream() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::new());
        B::assert_analyzes_to(
            &*a,
            "\u{643}\u{628}\u{64A}\u{631}",
            &["\u{643}\u{628}\u{64A}\u{631}"],
        )?;
        B::assert_analyzes_to(
            &*a,
            "\u{643}\u{628}\u{64A}\u{631}\u{629}",
            &["\u{643}\u{628}\u{64A}\u{631}"],
        )?;
        // feminine marker
        a.close();
        Ok(())
    }

    /// Non-arabic text gets treated in a similar way as SimpleAnalyzer.
    fn test_english_input() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::new());
        B::assert_analyzes_to(&*a, "English text.", &["english", "text"])?;
        a.close();
        Ok(())
    }

    /// Test that custom stopwords work, and are not case-sensitive.
    fn test_custom_stopwords() -> Result<()> {
        let set = char_set(&["the", "and", "a"], false);
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::with_stop_words(set.clone()));
        B::assert_analyzes_to(&*a, "The quick brown fox.", &["quick", "brown", "fox"])?;
        a.close();
        Ok(())
    }

    fn test_with_stem_exclusion_set() -> Result<()> {
        let set = char_set(
            &["\u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}"],
            false,
        );
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::with_stem_exclusion_set(
            CharArraySet::empty_set(),
            &set,
        ));
        B::assert_analyzes_to(&*a, "\u{643}\u{628}\u{64A}\u{631}\u{629} the quick \u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}", &["\u{643}\u{628}\u{64A}\u{631}", "the", "quick", "\u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}"])?;
        B::assert_analyzes_to(&*a, "\u{643}\u{628}\u{64A}\u{631}\u{629} the quick \u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}", &["\u{643}\u{628}\u{64A}\u{631}", "the", "quick", "\u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}"])?;
        a.close();
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::with_stem_exclusion_set(
            CharArraySet::empty_set(),
            &CharArraySet::empty_set(),
        ));
        B::assert_analyzes_to(&*a, "\u{643}\u{628}\u{64A}\u{631}\u{629} the quick \u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}", &["\u{643}\u{628}\u{64A}\u{631}", "the", "quick", "\u{633}\u{627}\u{647}\u{62F}"])?;
        B::assert_analyzes_to(&*a, "\u{643}\u{628}\u{64A}\u{631}\u{629} the quick \u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}", &["\u{643}\u{628}\u{64A}\u{631}", "the", "quick", "\u{633}\u{627}\u{647}\u{62F}"])?;
        a.close();
        Ok(())
    }

    /// test we fold digits to latin-1
    fn test_digits() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::new());
        B::check_one_term(&*a, "\u{661}\u{662}\u{663}\u{664}", "1234")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(ArabicAnalyzer::new());
        B::check_random_data(&*random(), &a, 200 * mult())?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.ar.TestArabicAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasicFeatures", test_basic_features))
            .method(t("testReusableTokenStream", test_reusable_token_stream))
            .method(t("testEnglishInput", test_english_input))
            .method(t("testCustomStopwords", test_custom_stopwords))
            .method(t("testWithStemExclusionSet", test_with_stem_exclusion_set))
            .method(t("testDigits", test_digits))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

#[test]
fn test_arabic_analyzer() {
    run(test_arabic_analyzer::class);
}

// -----------------------------------------------------------------------------
// TestArabicFilters
// -----------------------------------------------------------------------------

mod test_arabic_filters {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.ar";

    /// Test ArabicNormalizationFilterFactory
    fn test_normalizer() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new("\u{627}\u{644}\u{630}\u{64A}\u{646} \u{645}\u{64E}\u{644}\u{643}\u{62A} \u{623}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}"));
        let tokenizer = B::whitespace_mock_tokenizer(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "ArabicNormalization", &[])?.create(boxed(tokenizer))?;
        B::assert_token_stream_contents(
            &mut *stream,
            &[
                "\u{627}\u{644}\u{630}\u{64A}\u{646}",
                "\u{645}\u{644}\u{643}\u{62A}",
                "\u{627}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}",
            ],
        )?;
        Ok(())
    }

    /// Test ArabicStemFilterFactory
    fn test_stemmer() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new("\u{627}\u{644}\u{630}\u{64A}\u{646} \u{645}\u{64E}\u{644}\u{643}\u{62A} \u{623}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}"));
        let tokenizer = B::whitespace_mock_tokenizer(reader)?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "ArabicNormalization", &[])?.create(boxed(tokenizer))?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "ArabicStem", &[])?.create(stream)?;
        B::assert_token_stream_contents(
            &mut *stream,
            &[
                "\u{630}\u{64A}\u{646}",
                "\u{645}\u{644}\u{643}\u{62A}",
                "\u{627}\u{64A}\u{645}\u{627}\u{646}\u{643}\u{645}",
            ],
        )?;
        Ok(())
    }

    /// Test PersianCharFilterFactory
    fn test_persian_char_filter() -> Result<()> {
        let reader: Box<dyn CharReader> =
            char_filter_factory(PKG, "Persian", &[])?.create(Box::new(StringCharReader::new(
                "\u{645}\u{6CC}\u{200C}\u{62E}\u{648}\u{631}\u{62F}",
            )))?;
        let tokenizer = B::whitespace_mock_tokenizer(reader)?;
        B::assert_token_stream_contents(
            &mut *boxed(tokenizer),
            &["\u{645}\u{6CC}", "\u{62E}\u{648}\u{631}\u{62F}"],
        )?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected = iae_message(|| {
            token_filter_factory(PKG, "ArabicNormalization", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        let expected =
            iae_message(|| token_filter_factory(PKG, "Arabicstem", &["bogusArg", "bogusValue"]));
        Assert::assert_true(expected.contains("Unknown parameters"));
        let expected =
            iae_message(|| char_filter_factory(PKG, "Persian", &["bogusArg", "bogusValue"]));
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.ar.TestArabicFilters")
            .method(t("testNormalizer", test_normalizer))
            .method(t("testStemmer", test_stemmer))
            .method(t("testPersianCharFilter", test_persian_char_filter))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

