// -----------------------------------------------------------------------------
// TestBengaliFilters
// -----------------------------------------------------------------------------

mod test_bengali_filters {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.bn";

    /// Test IndicNormalizationFilterFactory
    fn test_indic_normalizer() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new(
            "\u{9A4}\u{9CD}\u{200D} \u{986}\u{9AE}\u{9BF}",
        ));
        let stream = B::whitespace_mock_tokenizer(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndicNormalization", &[])?.create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["\u{9CE}", "\u{986}\u{9AE}\u{9BF}"])?;
        Ok(())
    }

    /// Test BengaliNormalizationFilterFactory
    fn test_bengali_normalizer() -> Result<()> {
        let reader: Box<dyn CharReader> =
            Box::new(StringCharReader::new("\u{9AC}\u{9BE}\u{9DC}\u{9C0}"));
        let stream = B::whitespace_mock_tokenizer(reader)?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndicNormalization", &[])?.create(boxed(stream))?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "BengaliNormalization", &[])?.create(stream)?;
        B::assert_token_stream_contents(&mut *stream, &["\u{9AC}\u{9BE}\u{9B0}\u{9BF}"])?;
        Ok(())
    }

    /// Test BengaliStemFilterFactory
    fn test_stemmer() -> Result<()> {
        let reader: Box<dyn CharReader> =
            Box::new(StringCharReader::new("\u{9AC}\u{9BE}\u{9DC}\u{9C0}"));
        let stream = B::whitespace_mock_tokenizer(reader)?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndicNormalization", &[])?.create(boxed(stream))?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "BengaliNormalization", &[])?.create(stream)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "BengaliStem", &[])?.create(stream)?;
        B::assert_token_stream_contents(&mut *stream, &["\u{9AC}\u{9BE}\u{9B0}"])?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected = iae_message(|| {
            token_filter_factory(PKG, "IndicNormalization", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        let expected = iae_message(|| {
            token_filter_factory(PKG, "BengaliNormalization", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        let expected =
            iae_message(|| token_filter_factory(PKG, "BengaliStem", &["bogusArg", "bogusValue"]));
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.bn.TestBengaliFilters")
            .method(t("testIndicNormalizer", test_indic_normalizer))
            .method(t("testBengaliNormalizer", test_bengali_normalizer))
            .method(t("testStemmer", test_stemmer))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

#[test]
fn test_bengali_filters() {
    run(test_bengali_filters::class);
}

