// TestBengaliStemmer
// -----------------------------------------------------------------------------

mod test_bengali_stemmer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::bn::bengali_stem_filter::new_bengali_stem_filter;

    /// Testing few verbal words
    fn test_verbs_in_shadhu_form() -> Result<()> {
        check(
            "\u{995}\u{9B0}\u{9C7}\u{99B}\u{9BF}\u{9B2}\u{9BE}\u{9AE}",
            "\u{995}\u{9B0}",
        )?;
        check(
            "\u{995}\u{9B0}\u{9BF}\u{9A4}\u{9C7}\u{99B}\u{9BF}\u{9B2}\u{9C7}",
            "\u{995}\u{9B0}",
        )?;
        check(
            "\u{996}\u{9BE}\u{987}\u{9A4}\u{9BE}\u{9AE}",
            "\u{996}\u{9BE}\u{987}",
        )?;
        check("\u{9AF}\u{9BE}\u{987}\u{9AC}\u{9C7}", "\u{9AF}\u{9BE}")?;
        Ok(())
    }

    fn test_verbs_in_cholito_form() -> Result<()> {
        check(
            "\u{995}\u{9B0}\u{99B}\u{9BF}\u{9B2}\u{9BE}\u{9AE}",
            "\u{995}\u{9B0}",
        )?;
        check(
            "\u{995}\u{9B0}\u{99B}\u{9BF}\u{9B2}\u{9C7}",
            "\u{995}\u{9B0}",
        )?;
        check("\u{995}\u{9B0}\u{9A4}\u{9BE}\u{9AE}", "\u{995}\u{9B0}")?;
        check("\u{9AF}\u{9BE}\u{9AC}", "\u{9AF}\u{9BE}")?;
        check("\u{9AF}\u{9BE}\u{9AC}\u{9C7}", "\u{9AF}\u{9BE}")?;
        check("\u{995}\u{9B0}\u{9BF}", "\u{995}\u{9B0}")?;
        check("\u{995}\u{9B0}\u{9CB}", "\u{995}\u{9B0}")?;
        Ok(())
    }

    fn test_nouns() -> Result<()> {
        check(
            "\u{9AE}\u{9C7}\u{9DF}\u{9C7}\u{9B0}\u{9BE}",
            "\u{9AE}\u{9C7}",
        )?;
        check(
            "\u{9AE}\u{9C7}\u{9DF}\u{9C7}\u{9A6}\u{9C7}\u{9B0}\u{995}\u{9C7}",
            "\u{9AE}\u{9C7}",
        )?;
        check(
            "\u{9AE}\u{9C7}\u{9DF}\u{9C7}\u{9A6}\u{9C7}\u{9B0}",
            "\u{9AE}\u{9C7}",
        )?;
        check("\u{98F}\u{995}\u{99F}\u{9BF}", "\u{98F}\u{995}")?;
        check(
            "\u{9AE}\u{9BE}\u{9A8}\u{9C1}\u{9B7}\u{997}\u{9C1}\u{9B2}\u{9BF}",
            "\u{9AE}\u{9BE}\u{9A8}\u{9C1}\u{9B7}",
        )?;
        Ok(())
    }

    fn check(input: &str, output: &str) -> Result<()> {
        let tokenizer = B::whitespace_mock_tokenizer_str(input)?;
        let mut tf: Box<dyn TokenStream> = boxed(new_bengali_stem_filter(boxed(tokenizer))?);
        B::assert_token_stream_contents(&mut *tf, &[output])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.bn.TestBengaliStemmer$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_bengali_stem_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.bn.TestBengaliStemmer")
            .method(t("testVerbsInShadhuForm", test_verbs_in_shadhu_form))
            .method(t("testVerbsInCholitoForm", test_verbs_in_cholito_form))
            .method(t("testNouns", test_nouns))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

