mod test_hindi_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::hi::hindi_analyzer::HindiAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        HindiAnalyzer::new().close();
        Ok(())
    }

    fn test_basics() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(HindiAnalyzer::new());
        // two ways to write 'hindi' itself.
        B::check_one_term(
            &*a,
            "\u{939}\u{93F}\u{928}\u{94D}\u{926}\u{940}",
            "\u{939}\u{93F}\u{902}\u{926}",
        )?;
        B::check_one_term(
            &*a,
            "\u{939}\u{93F}\u{902}\u{926}\u{940}",
            "\u{939}\u{93F}\u{902}\u{926}",
        )?;
        a.close();
        Ok(())
    }

    fn test_exclusion_set() -> Result<()> {
        let exclusion_set = char_set(&["\u{939}\u{93F}\u{902}\u{926}\u{940}"], false);
        let a: Arc<dyn Analyzer> = Arc::new(HindiAnalyzer::with_stem_exclusion_set(
            HindiAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(
            &*a,
            "\u{939}\u{93F}\u{902}\u{926}\u{940}",
            "\u{939}\u{93F}\u{902}\u{926}\u{940}",
        )?;
        a.close();
        Ok(())
    }

    /// test we fold digits to latin-1
    fn test_digits() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(HindiAnalyzer::new());
        B::check_one_term(&*a, "\u{967}\u{968}\u{969}\u{96A}", "1234")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(HindiAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.hi.TestHindiAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasics", test_basics))
            .method(t("testExclusionSet", test_exclusion_set))
            .method(t("testDigits", test_digits))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

