fn test_hindi_analyzer() {
    run(test_hindi_analyzer::class);
}

// -----------------------------------------------------------------------------
// TestHindiFilters
// -----------------------------------------------------------------------------

mod test_hindi_filters {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.hi";

    /// Test IndicNormalizationFilterFactory
    fn test_indic_normalizer() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new(
            "\u{9A4}\u{9CD}\u{200D} \u{905}\u{93E}\u{948}\u{930}",
        ));
        let stream = B::whitespace_mock_tokenizer(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndicNormalization", &[])?.create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["\u{9CE}", "\u{914}\u{930}"])?;
        Ok(())
    }

    /// Test HindiNormalizationFilterFactory
    fn test_hindi_normalizer() -> Result<()> {
        let reader: Box<dyn CharReader> =
            Box::new(StringCharReader::new("\u{958}\u{93F}\u{924}\u{93E}\u{92C}"));
        let stream = B::whitespace_mock_tokenizer(reader)?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndicNormalization", &[])?.create(boxed(stream))?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "HindiNormalization", &[])?.create(stream)?;
        B::assert_token_stream_contents(&mut *stream, &["\u{915}\u{93F}\u{924}\u{93E}\u{92C}"])?;
        Ok(())
    }

    /// Test HindiStemFilterFactory
    fn test_stemmer() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new(
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}\u{947}\u{902}",
        ));
        let stream = B::whitespace_mock_tokenizer(reader)?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "IndicNormalization", &[])?.create(boxed(stream))?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "HindiNormalization", &[])?.create(stream)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "HindiStem", &[])?.create(stream)?;
        B::assert_token_stream_contents(&mut *stream, &["\u{915}\u{93F}\u{924}\u{93E}\u{92C}"])?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected = iae_message(|| {
            token_filter_factory(PKG, "IndicNormalization", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        let expected = iae_message(|| {
            token_filter_factory(PKG, "HindiNormalization", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        let expected =
            iae_message(|| token_filter_factory(PKG, "HindiStem", &["bogusArg", "bogusValue"]));
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.hi.TestHindiFilters")
            .method(t("testIndicNormalizer", test_indic_normalizer))
            .method(t("testHindiNormalizer", test_hindi_normalizer))
            .method(t("testStemmer", test_stemmer))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

#[test]
fn test_hindi_filters() {
    run(test_hindi_filters::class);
}

// -----------------------------------------------------------------------------
// TestHindiNormalizer
// -----------------------------------------------------------------------------

mod test_hindi_normalizer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::hi::hindi_normalization_filter::new_hindi_normalization_filter;

    /// Test some basic normalization, with an example from the paper.
    fn test_basics() -> Result<()> {
        check(
            "\u{905}\u{901}\u{917}\u{930}\u{947}\u{91C}\u{93C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        check(
            "\u{905}\u{901}\u{917}\u{930}\u{947}\u{91C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        check(
            "\u{905}\u{901}\u{917}\u{94D}\u{930}\u{947}\u{91C}\u{93C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        check(
            "\u{905}\u{901}\u{917}\u{94D}\u{930}\u{947}\u{91C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        check(
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        check(
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        check(
            "\u{905}\u{902}\u{917}\u{94D}\u{930}\u{947}\u{91C}\u{93C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        check(
            "\u{905}\u{902}\u{917}\u{94D}\u{930}\u{947}\u{91C}\u{940}",
            "\u{905}\u{902}\u{917}\u{930}\u{947}\u{91C}\u{93F}",
        )?;
        Ok(())
    }

    fn test_decompositions() -> Result<()> {
        // removing nukta dot
        check(
            "\u{958}\u{93F}\u{924}\u{93E}\u{92C}",
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}",
        )?;
        check("\u{95E}\u{930}\u{94D}\u{95B}", "\u{92B}\u{930}\u{91C}")?;
        check("\u{958}\u{930}\u{94D}\u{95B}", "\u{915}\u{930}\u{91C}")?;
        // some other composed nukta forms
        check(
            "\u{931}\u{934}\u{959}\u{95A}\u{95C}\u{95D}\u{95F}",
            "\u{930}\u{933}\u{916}\u{917}\u{921}\u{922}\u{92F}",
        )?;
        // removal of format (ZWJ/ZWNJ)
        check(
            "\u{936}\u{93E}\u{930}\u{94D}\u{200D}\u{92E}\u{93E}",
            "\u{936}\u{93E}\u{930}\u{92E}\u{93E}",
        )?;
        check(
            "\u{936}\u{93E}\u{930}\u{94D}\u{200C}\u{92E}\u{93E}",
            "\u{936}\u{93E}\u{930}\u{92E}\u{93E}",
        )?;
        // removal of chandra
        check(
            "\u{945}\u{946}\u{949}\u{94A}\u{90D}\u{90E}\u{911}\u{912}\u{972}",
            "\u{947}\u{947}\u{94B}\u{94B}\u{90F}\u{90F}\u{913}\u{913}\u{905}",
        )?;
        // vowel shortening
        check("\u{906}\u{908}\u{90A}\u{960}\u{961}\u{910}\u{914}\u{940}\u{942}\u{944}\u{963}\u{948}\u{94C}", "\u{905}\u{907}\u{909}\u{90B}\u{90C}\u{90F}\u{913}\u{93F}\u{941}\u{943}\u{962}\u{947}\u{94B}")?;
        Ok(())
    }

    fn check(input: &str, output: &str) -> Result<()> {
        let tokenizer = B::whitespace_mock_tokenizer_str(input)?;
        let mut tf: Box<dyn TokenStream> = boxed(new_hindi_normalization_filter(boxed(tokenizer))?);
        B::assert_token_stream_contents(&mut *tf, &[output])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.hi.TestHindiNormalizer$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_hindi_normalization_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.hi.TestHindiNormalizer")
            .method(t("testBasics", test_basics))
            .method(t("testDecompositions", test_decompositions))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

