fn test_hindi_normalizer() {
    run(test_hindi_normalizer::class);
}

// -----------------------------------------------------------------------------
// TestHindiStemmer
// -----------------------------------------------------------------------------

mod test_hindi_stemmer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::hi::hindi_stem_filter::new_hindi_stem_filter;

    /// Test masc noun inflections
    fn test_masculine_nouns() -> Result<()> {
        check("\u{932}\u{921}\u{915}\u{93E}", "\u{932}\u{921}\u{915}")?;
        check("\u{932}\u{921}\u{915}\u{947}", "\u{932}\u{921}\u{915}")?;
        check(
            "\u{932}\u{921}\u{915}\u{94B}\u{902}",
            "\u{932}\u{921}\u{915}",
        )?;
        check("\u{917}\u{941}\u{930}\u{941}", "\u{917}\u{941}\u{930}")?;
        check(
            "\u{917}\u{941}\u{930}\u{941}\u{913}\u{902}",
            "\u{917}\u{941}\u{930}",
        )?;
        check(
            "\u{926}\u{94B}\u{938}\u{94D}\u{924}",
            "\u{926}\u{94B}\u{938}\u{94D}\u{924}",
        )?;
        check(
            "\u{926}\u{94B}\u{938}\u{94D}\u{924}\u{94B}\u{902}",
            "\u{926}\u{94B}\u{938}\u{94D}\u{924}",
        )?;
        Ok(())
    }

    /// Test feminine noun inflections
    fn test_feminine_nouns() -> Result<()> {
        check("\u{932}\u{921}\u{915}\u{940}", "\u{932}\u{921}\u{915}")?;
        check(
            "\u{932}\u{921}\u{915}\u{93F}\u{92F}\u{94B}\u{902}",
            "\u{932}\u{921}\u{915}",
        )?;
        check(
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}",
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}",
        )?;
        check(
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}\u{947}\u{902}",
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}",
        )?;
        check(
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}\u{94B}\u{902}",
            "\u{915}\u{93F}\u{924}\u{93E}\u{92C}",
        )?;
        check(
            "\u{906}\u{927}\u{94D}\u{92F}\u{93E}\u{92A}\u{940}\u{915}\u{93E}",
            "\u{906}\u{927}\u{94D}\u{92F}\u{93E}\u{92A}\u{940}\u{915}",
        )?;
        check(
            "\u{906}\u{927}\u{94D}\u{92F}\u{93E}\u{92A}\u{940}\u{915}\u{93E}\u{90F}\u{902}",
            "\u{906}\u{927}\u{94D}\u{92F}\u{93E}\u{92A}\u{940}\u{915}",
        )?;
        check(
            "\u{906}\u{927}\u{94D}\u{92F}\u{93E}\u{92A}\u{940}\u{915}\u{93E}\u{913}\u{902}",
            "\u{906}\u{927}\u{94D}\u{92F}\u{93E}\u{92A}\u{940}\u{915}",
        )?;
        Ok(())
    }

    /// Test some verb forms
    fn test_verbs() -> Result<()> {
        check("\u{916}\u{93E}\u{928}\u{93E}", "\u{916}\u{93E}")?;
        check("\u{916}\u{93E}\u{924}\u{93E}", "\u{916}\u{93E}")?;
        check("\u{916}\u{93E}\u{924}\u{940}", "\u{916}\u{93E}")?;
        check("\u{916}\u{93E}", "\u{916}\u{93E}")?;
        Ok(())
    }

    /// From the paper: since the suffix list for verbs includes AI, awA and anI, additional suffixes
    /// had to be added to the list for noun/adjectives ending with these endings.
    fn test_exceptions() -> Result<()> {
        check(
            "\u{915}\u{920}\u{93F}\u{928}\u{93E}\u{907}\u{92F}\u{93E}\u{902}",
            "\u{915}\u{920}\u{93F}\u{928}",
        )?;
        check(
            "\u{915}\u{920}\u{93F}\u{928}",
            "\u{915}\u{920}\u{93F}\u{928}",
        )?;
        Ok(())
    }

    fn check(input: &str, output: &str) -> Result<()> {
        let tokenizer = B::whitespace_mock_tokenizer_str(input)?;
        let mut tf: Box<dyn TokenStream> = boxed(new_hindi_stem_filter(boxed(tokenizer))?);
        B::assert_token_stream_contents(&mut *tf, &[output])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.hi.TestHindiStemmer$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_hindi_stem_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.hi.TestHindiStemmer")
            .method(t("testMasculineNouns", test_masculine_nouns))
            .method(t("testFeminineNouns", test_feminine_nouns))
            .method(t("testVerbs", test_verbs))
            .method(t("testExceptions", test_exceptions))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

