// -----------------------------------------------------------------------------

mod test_nepali_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::ne::nepali_analyzer::NepaliAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        NepaliAnalyzer::new().close();
        Ok(())
    }

    /// test that snowball stemmer is hooked in correctly
    fn test_stemming() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(NepaliAnalyzer::new());
        // friend
        B::check_one_term(
            &*a,
            "\u{92E}\u{93F}\u{924}\u{94D}\u{930}",
            "\u{92E}\u{93F}\u{924}\u{94D}\u{930}",
        )?;
        // friends
        B::check_one_term(
            &*a,
            "\u{92E}\u{93F}\u{924}\u{94D}\u{930}\u{939}\u{930}\u{941}",
            "\u{92E}\u{93F}\u{924}\u{94D}\u{930}",
        )?;
        a.close();
        Ok(())
    }

    fn test_stopwords() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(NepaliAnalyzer::new());
        B::assert_analyzes_to(&*a, "\u{938}\u{92C}\u{948} \u{935}\u{94D}\u{92F}\u{915}\u{94D}\u{924}\u{93F}\u{939}\u{930}\u{942} \u{91C}\u{928}\u{94D}\u{92E}\u{91C}\u{93E}\u{924} \u{938}\u{94D}\u{935}\u{924}\u{928}\u{94D}\u{924}\u{94D}\u{930} \u{939}\u{941}\u{928}\u{94D} \u{924}\u{940} \u{938}\u{92C}\u{948}\u{915}\u{94B} \u{938}\u{92E}\u{93E}\u{928} \u{905}\u{927}\u{93F}\u{915}\u{93E}\u{930} \u{930} \u{92E}\u{939}\u{924}\u{94D}\u{935}", &["\u{935}\u{94D}\u{92F}\u{915}\u{94D}\u{924}\u{93F}", "\u{91C}\u{928}\u{94D}\u{92E}\u{91C}\u{93E}\u{924}", "\u{938}\u{94D}\u{935}\u{924}\u{928}\u{94D}\u{924}\u{94D}\u{930}", "\u{938}\u{92C}\u{948}", "\u{938}\u{92E}\u{93E}\u{928}", "\u{905}\u{927}\u{93F}\u{915}\u{93E}\u{930}", "\u{92E}\u{939}\u{924}\u{94D}\u{935}"])?;
        a.close();
        Ok(())
    }

    /// nepali has no case, but any latin-1 etc should be casefolded
    fn test_lower_case() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(NepaliAnalyzer::new());
        B::check_one_term(&*a, "FIFA", "fifa")?;
        a.close();
        Ok(())
    }

    fn test_exclusion_set() -> Result<()> {
        let exclusion_set = char_set(
            &["\u{92E}\u{93F}\u{924}\u{94D}\u{930}\u{939}\u{930}\u{941}"],
            false,
        );
        let a: Arc<dyn Analyzer> = Arc::new(NepaliAnalyzer::with_stem_exclusion_set(
            NepaliAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(
            &*a,
            "\u{92E}\u{93F}\u{924}\u{94D}\u{930}\u{939}\u{930}\u{941}",
            "\u{92E}\u{93F}\u{924}\u{94D}\u{930}\u{939}\u{930}\u{941}",
        )?;
        a.close();
        Ok(())
    }

    /// test we fold digits to latin-1
    fn test_digits() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(NepaliAnalyzer::new());
        B::check_one_term(&*a, "\u{967}\u{968}\u{969}\u{96A}", "1234")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(NepaliAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.ne.TestNepaliAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testStemming", test_stemming))
            .method(t("testStopwords", test_stopwords))
            .method(t("testLowerCase", test_lower_case))
            .method(t("testExclusionSet", test_exclusion_set))
            .method(t("testDigits", test_digits))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

#[test]
fn test_nepali_analyzer() {
    run(test_nepali_analyzer::class);
}

