        // passive preterite subjunctive
        B::assert_analyzes_to(&*a, "\u{62E}\u{648}\u{631}\u{62F}\u{647} \u{634}\u{62F}\u{647} \u{628}\u{627}\u{634}\u{62F}", &["\u{62E}\u{648}\u{631}\u{62F}\u{647}"])?;
        // passive imperfective preterite subjunctive
        B::assert_analyzes_to(&*a, "\u{62E}\u{648}\u{631}\u{62F}\u{647} \u{645}\u{6CC}\u{200C}\u{634}\u{62F}\u{647} \u{628}\u{627}\u{634}\u{62F}", &["\u{62E}\u{648}\u{631}\u{62F}\u{647}"])?;
        // passive pluperfect subjunctive
