    /// This test shows how the combination of tokenization (breaking on zero-width non-joiner or
    /// space) and stopwords creates a light-stemming effect for nouns, removing the plural -ha.
    fn test_behavior_nouns() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(PersianAnalyzer::new());
        B::assert_analyzes_to(
            &*a,
            "\u{628}\u{631}\u{6AF} \u{647}\u{627}",
            &["\u{628}\u{631}\u{6AF}"],
        )?;
        B::assert_analyzes_to(
            &*a,
            "\u{628}\u{631}\u{6AF}\u{200C}\u{647}\u{627}",
            &["\u{628}\u{631}\u{6AF}"],
        )?;
        a.close();
        Ok(())
    }

    /// Test showing that non-persian text is treated very much like SimpleAnalyzer (lowercased, etc)
    fn test_behavior_non_persian() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(PersianAnalyzer::new());
        B::assert_analyzes_to(&*a, "English test.", &["english", "test"])?;
        a.close();
        Ok(())
    }

