mod test_persian_normalization_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::fa::persian_normalization_filter::new_persian_normalization_filter;

    fn test_farsi_yeh() -> Result<()> {
        check("\u{647}\u{627}\u{6CC}", "\u{647}\u{627}\u{64A}")?;
        Ok(())
    }

    fn test_yeh_barree() -> Result<()> {
        check("\u{647}\u{627}\u{6D2}", "\u{647}\u{627}\u{64A}")?;
        Ok(())
    }

    fn test_keheh() -> Result<()> {
        check(
            "\u{6A9}\u{634}\u{627}\u{646}\u{62F}\u{646}",
            "\u{643}\u{634}\u{627}\u{646}\u{62F}\u{646}",
        )?;
        Ok(())
    }

    fn test_heh_yeh() -> Result<()> {
        check(
            "\u{643}\u{62A}\u{627}\u{628}\u{6C0}",
            "\u{643}\u{62A}\u{627}\u{628}\u{647}",
        )?;
        Ok(())
    }

    fn test_heh_hamza_above() -> Result<()> {
        check(
            "\u{643}\u{62A}\u{627}\u{628}\u{647}\u{654}",
            "\u{643}\u{62A}\u{627}\u{628}\u{647}",
        )?;
        Ok(())
    }

    fn test_heh_goal() -> Result<()> {
        check(
            "\u{632}\u{627}\u{62F}\u{6C1}",
            "\u{632}\u{627}\u{62F}\u{647}",
        )?;
        Ok(())
    }

    fn check(input: &str, expected: &str) -> Result<()> {
        let token_stream = B::whitespace_mock_tokenizer_str(input)?;
        let mut filter: Box<dyn TokenStream> =
            boxed(new_persian_normalization_filter(boxed(token_stream))?);
        B::assert_token_stream_contents(&mut *filter, &[expected])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.fa.TestPersianNormalizationFilter$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_persian_normalization_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.fa.TestPersianNormalizationFilter")
            .method(t("testFarsiYeh", test_farsi_yeh))
            .method(t("testYehBarree", test_yeh_barree))
            .method(t("testKeheh", test_keheh))
            .method(t("testHehYeh", test_heh_yeh))
            .method(t("testHehHamzaAbove", test_heh_hamza_above))
            .method(t("testHehGoal", test_heh_goal))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

