// -----------------------------------------------------------------------------
// TestPersianNormalizationFilterFactory
// -----------------------------------------------------------------------------

mod test_persian_normalization_filter_factory {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;

    const PKG: &str = "org.apache.lucene.analysis.fa";

    /// Ensure the filter actually normalizes persian text.
    fn test_normalization() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new("\u{647}\u{627}\u{6CC}"));
        let stream = B::whitespace_mock_tokenizer(reader)?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "PersianNormalization", &[])?.create(boxed(stream))?;
        B::assert_token_stream_contents(&mut *stream, &["\u{647}\u{627}\u{64A}"])?;
        Ok(())
    }

    /// Test PersianStemFilterFactory
    fn test_stemmer() -> Result<()> {
        let reader: Box<dyn CharReader> = Box::new(StringCharReader::new("\u{6A9}\u{62A}\u{627}\u{628}\u{647}\u{627} \u{628}\u{647}\u{62A}\u{631}\u{6CC}\u{646} \u{62F}\u{648}\u{633}\u{62A}\u{627}\u{646}"));
        let tokenizer = B::whitespace_mock_tokenizer(reader)?;
        let stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "PersianNormalization", &[])?.create(boxed(tokenizer))?;
        let mut stream: Box<dyn TokenStream> =
            token_filter_factory(PKG, "PersianStem", &[])?.create(stream)?;
        B::assert_token_stream_contents(
            &mut *stream,
            &[
                "\u{643}\u{62A}\u{627}\u{628}",
                "\u{628}\u{647}",
                "\u{62F}\u{648}\u{633}\u{62A}",
            ],
        )?;
        Ok(())
    }

    /// Test that bogus arguments result in exception
    fn test_bogus_arguments() -> Result<()> {
        let expected = iae_message(|| {
            token_filter_factory(PKG, "PersianNormalization", &["bogusArg", "bogusValue"])
        });
        Assert::assert_true(expected.contains("Unknown parameters"));
        let expected =
            iae_message(|| token_filter_factory(PKG, "PersianStem", &["bogusArg", "bogusValue"]));
        Assert::assert_true(expected.contains("Unknown parameters"));
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        factory_class("org.apache.lucene.analysis.fa.TestPersianNormalizationFilterFactory")
            .method(t("testNormalization", test_normalization))
            .method(t("testStemmer", test_stemmer))
            .method(t("testBogusArguments", test_bogus_arguments))
            .build()
    }
}

#[test]
fn test_persian_normalization_filter_factory() {
    run(test_persian_normalization_filter_factory::class);
}

