mod test_persian_stem_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::fa::persian_stem_filter::new_persian_stem_filter;
    use rucene_analysis_common::analysis::miscellaneous::set_keyword_marker_filter::new_set_keyword_marker_filter;

    thread_local! {
        /// The `a` field.
        static A: RefCell<Option<Arc<dyn Analyzer>>> = const { RefCell::new(None) };
    }
    fn a() -> Arc<dyn Analyzer> {
        A.with(|f| Arc::clone(f.borrow().as_ref().expect("setUp")))
    }
    fn set_a(a: Arc<dyn Analyzer>) {
        A.with(|f| *f.borrow_mut() = Some(a));
    }

    fn set_up() -> Result<()> {
        LuceneTestCase::super_set_up();
        set_a(
            FnAnalyzer::new(
                "org.apache.lucene.analysis.fa.TestPersianStemFilter$1",
                move |_| {
                    let source = own(MockTokenizer::new(Arc::clone(&WHITESPACE), true)?);
                    let stream = boxed(new_persian_stem_filter(shared(&source))?);
                    Ok(components(
                        source,
                        rucene_test_framework::analysis::sink(BoxedStream(stream)),
                    ))
                },
            )
            .arc(),
        );
        Ok(())
    }

    fn tear_down() -> Result<()> {
        a().close();
        LuceneTestCase::super_tear_down();
        Ok(())
    }

    fn test_an_suffix() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{62F}\u{648}\u{633}\u{62A}\u{627}\u{646}",
            "\u{62F}\u{648}\u{633}\u{62A}",
        )?;
        Ok(())
    }

    fn test_ha_suffix() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{643}\u{62A}\u{627}\u{628}\u{647}\u{627}",
            "\u{643}\u{62A}\u{627}\u{628}",
        )?;
        Ok(())
    }

    fn test_at_suffix() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{62C}\u{627}\u{645}\u{62F}\u{627}\u{62A}",
            "\u{62C}\u{627}\u{645}\u{62F}",
        )?;
        Ok(())
    }

    fn test_yee_suffix() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{639}\u{644}\u{64A}\u{631}\u{636}\u{627}\u{64A}\u{64A}",
            "\u{639}\u{644}\u{64A}\u{631}\u{636}\u{627}",
        )?;
        Ok(())
    }

    fn test_ye_suffix() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{634}\u{627}\u{62F}\u{645}\u{627}\u{646}\u{64A}",
            "\u{634}\u{627}\u{62F}\u{645}\u{627}\u{646}",
        )?;
        Ok(())
    }

    fn test_tar_suffix() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{628}\u{627}\u{62D}\u{627}\u{644}\u{62A}\u{631}",
            "\u{628}\u{627}\u{62D}\u{627}\u{644}",
        )?;
        Ok(())
    }

    fn test_tarin_suffix() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{62E}\u{648}\u{628}\u{62A}\u{631}\u{64A}\u{646}",
            "\u{62E}\u{648}\u{628}",
        )?;
        Ok(())
    }

    fn test_shouldnt_stem() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{643}\u{628}\u{627}\u{628}",
            "\u{643}\u{628}\u{627}\u{628}",
        )?;
        Ok(())
    }

    fn test_non_arabic() -> Result<()> {
        B::check_one_term(&*a(), "English", "english")?;
        Ok(())
    }

    fn test_with_keyword_attribute() -> Result<()> {
        let mut set = CharArraySet::new(1, true);
        set.add("\u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}");
        let token_stream =
            B::whitespace_mock_tokenizer_str("\u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}")?;
        let mut filter: Box<dyn TokenStream> = boxed(new_persian_stem_filter(boxed(
            new_set_keyword_marker_filter(boxed(token_stream), set.clone())?,
        ))?);
        B::assert_token_stream_contents(
            &mut *filter,
            &["\u{633}\u{627}\u{647}\u{62F}\u{647}\u{627}\u{62A}"],
        )?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.fa.TestPersianStemFilter$2",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_persian_stem_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.fa.TestPersianStemFilter")
            .method(hook("setUp", set_up))
            .method(hook("tearDown", tear_down))
            .method(t("testAnSuffix", test_an_suffix))
            .method(t("testHaSuffix", test_ha_suffix))
            .method(t("testAtSuffix", test_at_suffix))
            .method(t("testYeeSuffix", test_yee_suffix))
            .method(t("testYeSuffix", test_ye_suffix))
            .method(t("testTarSuffix", test_tar_suffix))
            .method(t("testTarinSuffix", test_tarin_suffix))
            .method(t("testShouldntStem", test_shouldnt_stem))
            .method(t("testNonArabic", test_non_arabic))
            .method(t("testWithKeywordAttribute", test_with_keyword_attribute))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

