// -----------------------------------------------------------------------------
// TestSoraniStemFilter
// -----------------------------------------------------------------------------

mod test_sorani_stem_filter {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::ckb::sorani_analyzer::SoraniAnalyzer;
    use rucene_analysis_common::analysis::ckb::sorani_normalization_filter::new_sorani_normalization_filter;
    use rucene_analysis_common::analysis::ckb::sorani_stem_filter::new_sorani_stem_filter;

    const PKG: &str = "org.apache.lucene.analysis.ckb";

    thread_local! {
        /// The `a` field.
        static A: RefCell<Option<Arc<dyn Analyzer>>> = const { RefCell::new(None) };
    }
    fn a() -> Arc<dyn Analyzer> {
        A.with(|f| Arc::clone(f.borrow().as_ref().expect("setUp")))
    }
    fn set_a(a: Arc<dyn Analyzer>) {
        A.with(|f| *f.borrow_mut() = Some(a));
    }

    fn set_up() -> Result<()> {
        LuceneTestCase::super_set_up();
        set_a(Arc::new(SoraniAnalyzer::new()));
        Ok(())
    }

    fn tear_down() -> Result<()> {
        a().close();
        LuceneTestCase::super_tear_down();
        Ok(())
    }

    fn test_indefinite_singular() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{67E}\u{6CC}\u{627}\u{648}\u{6CE}\u{6A9}",
            "\u{67E}\u{6CC}\u{627}\u{648}",
        )?;
        // -ek
        B::check_one_term(
            &*a(),
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}\u{6CC}\u{6D5}\u{6A9}",
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}",
        )?;
        Ok(())
    }

    fn test_definite_singular() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{67E}\u{6CC}\u{627}\u{648}\u{6D5}\u{643}\u{6D5}",
            "\u{67E}\u{6CC}\u{627}\u{648}",
        )?;
        // -aka
        B::check_one_term(
            &*a(),
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}\u{643}\u{6D5}",
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}",
        )?;
        Ok(())
    }

    fn test_demonstrative_singular() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{6A9}\u{62A}\u{627}\u{648}\u{6CC}\u{6D5}",
            "\u{6A9}\u{62A}\u{627}\u{648}\u{6CC}",
        )?;
        // -a
        B::check_one_term(
            &*a(),
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}\u{6CC}\u{6D5}",
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}",
        )?;
        Ok(())
    }

    fn test_indefinite_plural() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{67E}\u{6CC}\u{627}\u{648}\u{627}\u{646}",
            "\u{67E}\u{6CC}\u{627}\u{648}",
        )?;
        // -An
        B::check_one_term(
            &*a(),
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}\u{6CC}\u{627}\u{646}",
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}",
        )?;
        Ok(())
    }

    fn test_definite_plural() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{67E}\u{6CC}\u{627}\u{648}\u{6D5}\u{6A9}\u{627}\u{646}",
            "\u{67E}\u{6CC}\u{627}\u{648}",
        )?;
        // -akAn
        B::check_one_term(
            &*a(),
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}\u{6A9}\u{627}\u{646}",
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}",
        )?;
        Ok(())
    }

    fn test_demonstrative_plural() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{67E}\u{6CC}\u{627}\u{648}\u{627}\u{646}\u{6D5}",
            "\u{67E}\u{6CC}\u{627}\u{648}",
        )?;
        // -Ana
        B::check_one_term(
            &*a(),
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}\u{6CC}\u{627}\u{646}\u{6D5}",
            "\u{62F}\u{6D5}\u{631}\u{6AF}\u{627}",
        )?;
        Ok(())
    }

    fn test_ezafe() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{647}\u{6C6}\u{62A}\u{6CC}\u{644}\u{6CC}",
            "\u{647}\u{6C6}\u{62A}\u{6CC}\u{644}",
        )?;
        // singular
        B::check_one_term(
            &*a(),
            "\u{647}\u{6C6}\u{62A}\u{6CC}\u{644}\u{6CE}\u{6A9}\u{6CC}",
            "\u{647}\u{6C6}\u{62A}\u{6CC}\u{644}",
        )?;
        // indefinite
        B::check_one_term(
            &*a(),
            "\u{647}\u{6C6}\u{62A}\u{6CC}\u{644}\u{627}\u{646}\u{6CC}",
            "\u{647}\u{6C6}\u{62A}\u{6CC}\u{644}",
        )?;
        Ok(())
    }

    fn test_postpositions() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{62F}\u{648}\u{648}\u{631}\u{6D5}\u{648}\u{6D5}",
            "\u{62F}\u{648}\u{648}\u{631}",
        )?;
        // -awa
        B::check_one_term(
            &*a(),
            "\u{646}\u{6CC}\u{648}\u{6D5}\u{634}\u{6D5}\u{648}\u{62F}\u{627}",
            "\u{646}\u{6CC}\u{648}\u{6D5}\u{634}\u{6D5}\u{648}",
        )?;
        // -dA
        B::check_one_term(
            &*a(),
            "\u{633}\u{6C6}\u{631}\u{627}\u{646}\u{627}",
            "\u{633}\u{6C6}\u{631}\u{627}\u{646}",
        )?;
        Ok(())
    }

    fn test_possessives() -> Result<()> {
        B::check_one_term(
            &*a(),
            "\u{67E}\u{627}\u{631}\u{6D5}\u{645}\u{627}\u{646}",
            "\u{67E}\u{627}\u{631}\u{6D5}",
        )?;
        // -mAn
        B::check_one_term(
            &*a(),
            "\u{67E}\u{627}\u{631}\u{6D5}\u{62A}\u{627}\u{646}",
            "\u{67E}\u{627}\u{631}\u{6D5}",
        )?;
        // -tAn
        B::check_one_term(
            &*a(),
            "\u{67E}\u{627}\u{631}\u{6D5}\u{6CC}\u{627}\u{646}",
            "\u{67E}\u{627}\u{631}\u{6D5}",
        )?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.ckb.TestSoraniStemFilter$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_sorani_stem_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    /// test against a basic vocabulary file
    fn test_vocabulary() -> Result<()> {
        // top 8k words or so: freq > 1000
        // just normalization+stem, we are testing that the stemming doesn't break.
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.ckb.TestSoraniStemFilter$2",
            move |_| {
                let tokenizer = own(MockTokenizer::new(Arc::clone(&WHITESPACE), true)?);
                let stream = boxed(new_sorani_normalization_filter(shared(&tokenizer))?);
                let stream = boxed(new_sorani_stem_filter(stream)?);
                let stream = stream;
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        VocabularyAssert::assert_vocabulary_zip_tsv(
            &*a,
            &data_path(PKG, "ckbtestdata.zip")?,
            "testdata.txt",
        )?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.ckb.TestSoraniStemFilter")
            .method(hook("setUp", set_up))
            .method(hook("tearDown", tear_down))
            .method(t("testIndefiniteSingular", test_indefinite_singular))
            .method(t("testDefiniteSingular", test_definite_singular))
            .method(t("testDemonstrativeSingular", test_demonstrative_singular))
            .method(t("testIndefinitePlural", test_indefinite_plural))
            .method(t("testDefinitePlural", test_definite_plural))
            .method(t("testDemonstrativePlural", test_demonstrative_plural))
            .method(t("testEzafe", test_ezafe))
            .method(t("testPostpositions", test_postpositions))
            .method(t("testPossessives", test_possessives))
            .method(t("testEmptyTerm", test_empty_term))
            .method(t("testVocabulary", test_vocabulary))
            .build()
    }
}

