mod test_tamil_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::ta::tamil_analyzer::TamilAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        TamilAnalyzer::new().close();
        Ok(())
    }

    /// test that snowball stemmer is hooked in
    fn test_stemming() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(TamilAnalyzer::new());
        // friend
        B::check_one_term(
            &*a,
            "\u{BA8}\u{BA3}\u{BCD}\u{BAA}\u{BA9}\u{BCD}",
            "\u{BA8}\u{BA3}\u{BCD}",
        )?;
        // friends
        B::check_one_term(
            &*a,
            "\u{BA8}\u{BA3}\u{BCD}\u{BAA}\u{BB0}\u{BCD}\u{B95}\u{BB3}\u{BCD}",
            "\u{BA8}\u{BA3}\u{BCD}",
        )?;
        a.close();
        Ok(())
    }

    fn test_exclusion_set() -> Result<()> {
        let exclusion_set = char_set(
            &["\u{BA8}\u{BA3}\u{BCD}\u{BAA}\u{BB0}\u{BCD}\u{B95}\u{BB3}\u{BCD}"],
            false,
        );
        let a: Arc<dyn Analyzer> = Arc::new(TamilAnalyzer::with_stem_exclusion_set(
            TamilAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(
            &*a,
            "\u{BA8}\u{BA3}\u{BCD}\u{BAA}\u{BB0}\u{BCD}\u{B95}\u{BB3}\u{BCD}",
            "\u{BA8}\u{BA3}\u{BCD}\u{BAA}\u{BB0}\u{BCD}\u{B95}\u{BB3}\u{BCD}",
        )?;
        a.close();
        Ok(())
    }

    /// test we fold digits to latin-1
    fn test_digits() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(TamilAnalyzer::new());
        B::check_one_term(&*a, "\u{BE7}\u{BE8}\u{BE9}\u{BEA}", "1234")?;
        a.close();
        Ok(())
    }

    /// tamil doesn't have case, but test we case-fold any latin-1 etc
    fn test_lower_case() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(TamilAnalyzer::new());
        B::check_one_term(&*a, "FIFA", "fifa")?;
        a.close();
        Ok(())
    }

    /// blast some random strings through the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(TamilAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.ta.TestTamilAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testStemming", test_stemming))
            .method(t("testExclusionSet", test_exclusion_set))
            .method(t("testDigits", test_digits))
            .method(t("testLowerCase", test_lower_case))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

