// -----------------------------------------------------------------------------

mod test_telugu_analyzer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene::util::BytesRef;
    use rucene_analysis_common::analysis::te::telugu_analyzer::TeluguAnalyzer;

    /// This test fails with NPE when the stopwords file is missing in classpath
    fn test_resources_available() -> Result<()> {
        TeluguAnalyzer::new().close();
        Ok(())
    }

    fn test_basics() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(TeluguAnalyzer::new());
        // two ways to write oo letter.
        B::check_one_term(
            &*a,
            "\u{C12}\u{C55}\u{C28}\u{C2E}\u{C3E}\u{C32}",
            "\u{C13}\u{C28}\u{C2E}\u{C3E}\u{C32}",
        )?;
        a.close();
        Ok(())
    }

    fn test_exclusion_set() -> Result<()> {
        let exclusion_set = char_set(
            &["\u{C35}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C35}\u{C41}\u{C32}\u{C41}"],
            false,
        );
        let a: Arc<dyn Analyzer> = Arc::new(TeluguAnalyzer::with_stem_exclusion_set(
            TeluguAnalyzer::get_default_stop_set().clone(),
            &exclusion_set,
        ));
        B::check_one_term(
            &*a,
            "\u{C35}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C35}\u{C41}\u{C32}\u{C41}",
            "\u{C35}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C2E}\u{C32}\u{C41}",
        )?;
        a.close();
        Ok(())
    }

    /// test we fold digits to latin-1
    fn test_digits() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(TeluguAnalyzer::new());
        B::check_one_term(&*a, "\u{C67}\u{C68}\u{C69}\u{C6A}", "1234")?;
        a.close();
        Ok(())
    }

    fn test_normalization() -> Result<()> {
        let a: Arc<dyn Analyzer> = Arc::new(TeluguAnalyzer::new());
        // DecimalDigitsFilter
        Assert::assert_true(
            BytesRef::from_char_sequence("1234")
                == a.normalize("dummy", "\u{C67}\u{C68}\u{C69}\u{C6A}")?,
        );
        // IndicNormalizationFilter
        Assert::assert_true(
            BytesRef::from_char_sequence("\u{911}\u{911}")
                == a.normalize("dummy", "\u{905}\u{93E}\u{945}\u{905}\u{93E}\u{945}")?,
        );
        // TeluguNormalizationFilter
        Assert::assert_true(
            BytesRef::from_char_sequence("\u{C13}\u{C28}\u{C2E}\u{C3E}\u{C32}")
                == a.normalize("dummy", "\u{C12}\u{C55}\u{C28}\u{C2E}\u{C3E}\u{C32}")?,
        );
        a.close();
        Ok(())
    }

    /// Send some random strings to the analyzer
    fn test_random_strings() -> Result<()> {
        let analyzer: Arc<dyn Analyzer> = Arc::new(TeluguAnalyzer::new());
        B::check_random_data(&*random(), &analyzer, 200 * mult())?;
        analyzer.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.te.TestTeluguAnalyzer")
            .method(t("testResourcesAvailable", test_resources_available))
            .method(t("testBasics", test_basics))
            .method(t("testExclusionSet", test_exclusion_set))
            .method(t("testDigits", test_digits))
            .method(t("testNormalization", test_normalization))
            .method(t("testRandomStrings", test_random_strings))
            .build()
    }
}

