// -----------------------------------------------------------------------------
// TestTeluguNormalizer
// -----------------------------------------------------------------------------

mod test_telugu_normalizer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::te::telugu_normalization_filter::new_telugu_normalization_filter;

    /// Long matras should be shortened.
    fn test_matra() -> Result<()> {
        check(
            "\u{C2A}\u{C26}\u{C3E}\u{C32}\u{C42}",
            "\u{C2A}\u{C26}\u{C3E}\u{C32}\u{C41}",
        )?;
        check(
            "\u{C05}\u{C2C}\u{C4D}\u{C2C}\u{C3E}\u{C2F}\u{C40}",
            "\u{C05}\u{C2C}\u{C4D}\u{C2C}\u{C3E}\u{C2F}\u{C3F}",
        )?;
        Ok(())
    }

    fn test_vowels() -> Result<()> {
        // removal of visarga (ః)
        check(
            "\u{C03}\u{C4C}\u{C48}\u{C3E}\u{C3F}\u{C41}",
            "\u{C4C}\u{C48}\u{C3E}\u{C3F}\u{C41}",
        )?;
        // vowel shortening
        check(
            "\u{C14}\u{C10}\u{C06}\u{C08}\u{C0A}",
            "\u{C13}\u{C0F}\u{C05}\u{C07}\u{C09}",
        )?;
        Ok(())
    }

    fn check(input: &str, output: &str) -> Result<()> {
        let tokenizer = B::whitespace_mock_tokenizer_str(input)?;
        let mut tf: Box<dyn TokenStream> =
            boxed(new_telugu_normalization_filter(boxed(tokenizer))?);
        B::assert_token_stream_contents(&mut *tf, &[output])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.te.TestTeluguNormalizer$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_telugu_normalization_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.te.TestTeluguNormalizer")
            .method(t("testMatra", test_matra))
            .method(t("testVowels", test_vowels))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

#[test]
fn test_telugu_normalizer() {
    run(test_telugu_normalizer::class);
}

