mod test_telugu_stemmer {
    #![allow(unused_imports, clippy::redundant_clone)]
    use super::*;
    use rucene_analysis_common::analysis::te::telugu_stem_filter::new_telugu_stem_filter;

    /// Test plural forms
    fn test_plurals() -> Result<()> {
        check(
            "\u{C35}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C35}\u{C41}\u{C32}\u{C41}",
            "\u{C35}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C35}\u{C41}",
        )?;
        check(
            "\u{C2A}\u{C28}\u{C4D}\u{C28}\u{C41}\u{C32}\u{C41}",
            "\u{C2A}\u{C28}\u{C4D}\u{C28}\u{C41}",
        )?;
        Ok(())
    }

    /// Test some verb forms
    fn test_verbs() -> Result<()> {
        check("\u{C1A}\u{C47}\u{C2A}\u{C3F}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C28}\u{C4D}\u{C28}\u{C26}\u{C3F}", "\u{C1A}\u{C47}\u{C2A}\u{C3F}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C28}\u{C4D}\u{C28}")?;
        check("\u{C1A}\u{C47}\u{C2A}\u{C3F}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C28}\u{C4D}\u{C28}\u{C21}\u{C41}", "\u{C1A}\u{C47}\u{C2A}\u{C3F}\u{C38}\u{C4D}\u{C24}\u{C41}\u{C28}\u{C4D}\u{C28}")?;
        Ok(())
    }

    fn check(input: &str, output: &str) -> Result<()> {
        let tokenizer = B::whitespace_mock_tokenizer_str(input)?;
        let mut tf: Box<dyn TokenStream> = boxed(new_telugu_stem_filter(boxed(tokenizer))?);
        B::assert_token_stream_contents(&mut *tf, &[output])?;
        Ok(())
    }

    fn test_empty_term() -> Result<()> {
        let a: Arc<dyn Analyzer> = FnAnalyzer::new(
            "org.apache.lucene.analysis.te.TestTeluguStemmer$1",
            move |_| {
                let tokenizer = own(new_keyword_tokenizer());
                let stream = boxed(new_telugu_stem_filter(shared(&tokenizer))?);
                Ok(components(
                    tokenizer,
                    rucene_test_framework::analysis::sink(BoxedStream(stream)),
                ))
            },
        )
        .arc();
        B::check_one_term(&*a, "", "")?;
        a.close();
        Ok(())
    }

    pub fn class() -> Arc<Class> {
        btstc_class("org.apache.lucene.analysis.te.TestTeluguStemmer")
            .method(t("testPlurals", test_plurals))
            .method(t("testVerbs", test_verbs))
            .method(t("testEmptyTerm", test_empty_term))
            .build()
    }
}

